    %arg2: tensor<7xf32>,       // linear.bias
    %arg3: tensor<6x7xf32>      // input x
  ) -> tensor<6x7xf32> {
    // Linear: x @ W^T + b
    // PyTorch Linear: y = x @ W^T + b, where W is [out_features, in_features]
    // Our %arg1 is [7x7], so we need to transpose it for matmul with [6x7] input

    // Transpose weight: [7x7] -> [7x7] (no-op, but for clarity, let's show it)
    // Actually, since both are 7x7, and matmul is (6x7) x (7x7), we can use as is.

    // Matmul: [6x7] x [7x7] -> [6x7]
    %0 = "stablehlo.dot_general"(%arg3, %arg1) {
      dot_dimension_numbers = #stablehlo.dot<
        lhs_batching_dimensions = [],
        rhs_batching_dimensions = [],
        lhs_contracting_dimensions = [1],
        rhs_contracting_dimensions = [1]
      >
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Broadcast bias: [7] -> [6x7]
    %1 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

    // Add bias
    %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

    // Broadcast constant: [f32] -> [6x7]
    %3 = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>

    // Elementwise min with constant
    %4 = stablehlo.minimum %2, %3 : tensor<6x7xf32>

    // Subtract constant
    %5 = stablehlo.subtract %4, %3 : tensor<6x7xf32>

    return %5 : tensor<6x7xf32>
  }
