    %wT = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // Dot: [6,7] x [7,7] -> [6,7]
    %linear = "stablehlo.dot_general"(%arg3, %wT) {
      lhs_contracting_dimensions = dense<[1]> : tensor<1xi64>,
      rhs_contracting_dimensions = dense<[0]> : tensor<1xi64>,
      lhs_batching_dimensions = dense<[]> : tensor<0xi64>,
      rhs_batching_dimensions = dense<[]> : tensor<0xi64>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Broadcast bias [7] -> [6,7]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %linear_bias = "stablehlo.add"(%linear, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Broadcast constant [scalar] -> [6,7]
    %const_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
    // min(linear_bias, constant)
    %min = "stablehlo.minimum"(%linear_bias, %const_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Subtract constant
