module {
  // Implements: y = conv3d(x, weight), with
  //   x: tensor<8x3x16x7x7xf32>         (N, C_in, D, H, W)
  //   weight: tensor<6x3x3x5x7xf32>     (C_out, C_in, kD, kH, kW)
  // Output: tensor<8x6x14x3x1xf32>
  //
  // PyTorch nn.Conv3d with kernel_size=(3,5,7), stride=(1,5,7), padding=(0,1,3), dilation=(1,1,1), groups=1, bias=False
  // But from the signature and description, only kernel_size is set, all else default (stride=1, padding=0, dilation=1, groups=1, bias=False)
  // So: stride=(1,1,1), padding=(0,0,0), dilation=(1,1,1), groups=1

  func.func @main(
    %weight: tensor<6x3x3x5x7xf32>,   // (out_channels, in_channels, kD, kH, kW)
    %input: tensor<8x3x16x7x7xf32>    // (batch, in_channels, D, H, W)
  ) -> tensor<8x6x14x3x1xf32> {
    // StableHLO expects input: [N, D, H, W, C]
    // PyTorch: [N, C, D, H, W]
    // So, need to transpose input from [N, C, D, H, W] -> [N, D, H, W, C]
    %input_t = stablehlo.transpose(%input, [0, 2, 3, 4, 1]) : tensor<8x3x16x7x7xf32> to tensor<8x16x7x7x3xf32>

    // StableHLO expects kernel: [O, kD, kH, kW, I]
    // PyTorch: [O, I, kD, kH, kW]
    // So, need to transpose weight from [O, I, kD, kH, kW] -> [O, kD, kH, kW, I]
    %weight_t = stablehlo.transpose(%weight, [0, 2, 3, 4, 1]) : tensor<6x3x3x5x7xf32> to tensor<6x3x5x7x3xf32>

    // Convolution parameters:
    // window_strides: [1,1,1]
    // padding: [0,0,0,0,0,0] (no padding)
    // lhs_dilation: [1,1,1]
    // rhs_dilation: [1,1,1]
    // feature_group_count: 1
    // dimension_numbers:
    //   lhs_spec: [N, D, H, W, C]
    //   rhs_spec: [O, kD, kH, kW, I]
    //   out_spec: [N, D, H, W, O]

    %conv = stablehlo.convolution(
      %input_t, %weight_t,
      window_strides = [1, 1, 1],
      padding = [0, 0, 0, 0, 0, 0],
      lhs_dilation = [1, 1, 1],
      rhs_dilation = [1, 1, 1],
      feature_group_count = 1,
      batch_group_count = 1,
      dimension_numbers = [
        [0, 1, 2, 3, 4], // input: N, D, H, W, C
        [0, 1, 2, 3, 4], // kernel: O, kD, kH, kW, I
        [0, 1, 2, 3, 4]  // output: N, D, H, W, O
      ],
      precision_config = []
    ) : (tensor<8x16x7x7x3xf32>, tensor<6x3x5x7x3xf32>) -> tensor<8x14x3x1x6xf32>

    // Output is [N, D_out, H_out, W_out, O] = [8, 14, 3, 1, 6]
    // But required output is [8, 6, 14, 3, 1]
    // So, transpose output dims: [0, 4, 1, 2, 3]
    %out = stablehlo.transpose(%conv, [0, 4, 1, 2, 3]) : tensor<8x14x3x1x6xf32> to tensor<8x6x14x3x1xf32>

    return %out : tensor<8x6x14x3x1xf32>
  }
}
