  ) -> tensor<8x6x14x3x1xf32> {
    // PyTorch nn.Conv3d expects weight layout [out_c, in_c, kD, kH, kW]
    // StableHLO expects kernel layout [out_c, in_c, kD, kH, kW]
    // BUT: PyTorch input is [N, C, D, H, W], StableHLO expects [N, C, D, H, W]
    // So layouts match, but PyTorch's convolution flips the spatial kernel (cross-correlation vs convolution).
    // StableHLO does NOT flip the kernel (cross-correlation).
    // To match PyTorch, we must flip the kernel spatial dims: [kD, kH, kW] -> reversed.

    // Flip kernel spatial dims: [2, 3, 4] axes
    %flipped = "stablehlo.reverse"(%arg0) {dimensions = dense<[2, 3, 4]> : tensor<3xi64>} : (tensor<6x3x3x5x7xf32>) -> tensor<6x3x3x5x7xf32>

