    // Output shape math:
    //   D_out = floor((16 + 0 - 3)/1) + 1 = 14
    //   H_out = floor((7 + 2 - 5)/1) + 1 = 3
    //   W_out = floor((7 + 0 - 7)/1) + 1 = 1
    // So: stride = (1, 1, 1), padding = (0, 1, 0)
    %result = "stablehlo.convolution"(%arg1, %flipped) {
      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[0, 0], [1, 1], [0, 0]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
