    //   W_out = floor((7 + 0 - 1*(7-1) - 1)/1 + 1) = (7 - 6) + 1 = 2
    // But the output shape is (8,6,14,3,1), so it seems the output is sliced or cropped.
    // Let's check:
    //   D_out = 14 (not 15)
    //   H_out = 3 (not 4)
    //   W_out = 1 (not 2)
    // So, after convolution, we need to slice:
    //   D: 0:14
    //   H: 0:3
    //   W: 0:1

    // Perform convolution
    %conv = "stablehlo.convolution"(%arg1, %arg0) {
      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
      rhs_dilation = array<i64: 1, 1, 1>,
      dimension_numbers = #stablehlo.conv<[
