module {
  func.func @main(
    %arg0: tensor<f32>,         // constant
    %arg1: tensor<7x7xf32>,     // linear.weight
    %arg2: tensor<7xf32>,       // linear.bias
    %arg3: tensor<6x7xf32>      // input x
  ) -> tensor<6x7xf32> {
    // Linear: y = x @ W^T + b
    // %arg3: [6,7], %arg1: [7,7] (weight), want x @ W^T
    // Transpose weight to [7,7] (no-op, but explicit for clarity)
    %wT = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // Dot: [6,7] x [7,7] -> [6,7]
    %linear = "stablehlo.dot_general"(%arg3, %wT) {
      dot_dimension_numbers = #stablehlo.dot<
        lhs_contracting_dimensions = [1],
        rhs_contracting_dimensions = [0]
      >
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Broadcast bias [7] to [6,7]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %linear_bias = stablehlo.add %linear, %bias_bcast : tensor<6x7xf32>
    // Broadcast constant [scalar] to [6,7]
    %const_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
    // torch.min(x, constant): elementwise minimum
    %min = stablehlo.minimum %linear_bias, %const_bcast : tensor<6x7xf32>
    // Subtract constant
    %out = stablehlo.subtract %min, %const_bcast : tensor<6x7xf32>
    return %out : tensor<6x7xf32>
  }
}
