  func.func @main(%weight: tensor<7x7xf32>, %x: tensor<6x7xf32>) -> tensor<6x1xf32> {
    // 1. Transpose weight to shape [7,7] -> [7,7] (weight.T is just itself since it's square, but let's transpose for generality)
    %cst_perm = stablehlo.constant dense<[1,0]> : tensor<2xi64>
    %weight_t = stablehlo.transpose(%weight, %cst_perm) : (tensor<7x7xf32>, tensor<2xi64>) -> tensor<7x7xf32>
    // 2. Matmul: x [6,7] @ weight_t [7,7] -> [6,7]
    %dot = stablehlo.dot_general
      %x, %weight_t,
      {
        // lhs_contracting_dims = [1], rhs_contracting_dims = [0]
        // batch dims: none
        lhs_contracting_dims = dense<[1]> : tensor<1xi64>,
        rhs_contracting_dims = dense<[0]> : tensor<1xi64>,
        lhs_batching_dims = dense<[]> : tensor<0xi64>,
        rhs_batching_dims = dense<[]> : tensor<0xi64>
      }
      : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // 3. Divide by 2
    %cst_two = stablehlo.constant dense<2.0> : tensor<f32>
    %cst_two_bcast = stablehlo.broadcast_in_dim(%cst_two, dense<[]> : tensor<0xi64>) : (tensor<f32>, tensor<0xi64>) -> tensor<6x7xf32>
    %div = stablehlo.divide %dot, %cst_two_bcast : tensor<6x7xf32>
    // 4. Reduce sum along dim=1, keepdim=True
    %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
    %sum = stablehlo.reduce(%div, %cst_zero) {
      ^bb0(%a: f32, %b: f32):
        %add = stablehlo.add %a, %b : f32
        stablehlo.return %add : f32
    } {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>
    // 5. Multiply by scaling_factor=1.5
    %cst_scale = stablehlo.constant dense<1.5> : tensor<f32>
    %cst_scale_bcast = stablehlo.broadcast_in_dim(%cst_scale, dense<[]> : tensor<0xi64>) : (tensor<f32>, tensor<0xi64>) -> tensor<6x1xf32>
    %out = stablehlo.multiply %sum, %cst_scale_bcast : tensor<6x1xf32>
    return %out : tensor<6x1xf32>
  }
