module {
  // Entry function: 
  //   %arg0: weight parameter, tensor<7x7xf32>
  //   %arg1: input x, tensor<6x7xf32>
  // Returns: tensor<6x1xf32>
  func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<6x7xf32>) -> tensor<6x1xf32> {
    // 1. Transpose weight: (7x7) -> (7x7), but .T is just swap axes 0 and 1
    %weight_t = stablehlo.transpose(%arg0, [1, 0]) : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // 2. Matmul: x (6x7) @ weight.T (7x7) -> (6x7)
    // dot_general with batch dims [] and contracting dims [1] for x, [0] for weight_t
    %matmul = stablehlo.dot_general
      %arg1, %weight_t,
      {
        lhs_contracting_dimensions = dense<[1]> : tensor<1xi64>,
        rhs_contracting_dimensions = dense<[0]> : tensor<1xi64>,
        lhs_batch_dimensions = dense<[]> : tensor<0xi64>,
        rhs_batch_dimensions = dense<[]> : tensor<0xi64>
      }
      : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // 3. Divide by 2
    %cst_two = stablehlo.constant dense<2.0> : tensor<f32>
    %cst_two_bcast = stablehlo.broadcast_in_dim %cst_two, dims = [] : (tensor<f32>) -> tensor<6x7xf32>
    %div = stablehlo.divide %matmul, %cst_two_bcast : tensor<6x7xf32>
    // 4. Sum over dim=1 (columns), keepdim=True -> (6x1)
    %sum = stablehlo.reduce
      %div, %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
      applies stablehlo.add
      dimensions = [1]
      : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>
    // 5. Multiply by scaling_factor=1.5
    %cst_scale = stablehlo.constant dense<1.5> : tensor<f32>
    %cst_scale_bcast = stablehlo.broadcast_in_dim %cst_scale, dims = [] : (tensor<f32>) -> tensor<6x1xf32>
    %scaled = stablehlo.multiply %sum, %cst_scale_bcast : tensor<6x1xf32>
    return %scaled : tensor<6x1xf32>
  }
}
