    %0 = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3, 4>} : (tensor<6x7x3x3x3xf32>) -> tensor<6x7x3x3x3xf32>
    // 2. Swap in/out channels for convolution: [in_c, out_c, kD, kH, kW] -> [out_c, in_c, kD, kH, kW]
    %1 = "stablehlo.transpose"(%0) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<6x7x3x3x3xf32>) -> tensor<7x6x3x3x3xf32>
    // 3. Convolution (forward) with appropriate parameters for transposed conv
    //    - input: [N, in_c, D, H, W]
    //    - kernel: [out_c, in_c, kD, kH, kW]
    //    - output: [N, out_c, D_out, H_out, W_out]
    //    - stride = 1, dilation = 1, padding = 2, output_padding = 0
    //    - For transposed conv: lhs_dilation = stride, rhs_dilation = dilation, padding = kernel_size-1-padding
    //    - Here: stride=1, dilation=1, padding=0, kernel_size=3
    //    - So: lhs_dilation = 1, rhs_dilation = 1, padding = 2 (on both sides for each spatial dim)
    //    - Output shape: D_out = (D-1)*stride - 2*padding + dilation*(kernel_size-1) + output_padding + 1
    //      = (8-1)*1 - 2*0 + 1*(3-1) + 0 + 1 = 7 + 2 + 1 = 10
    %2 = "stablehlo.convolution"(%arg1, %1) {
      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[2, 2], [2, 2], [2, 2]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
      rhs_dilation = array<i64: 1, 1, 1>,
      // Corrected dimension_numbers: [b, i, 0, 1, 2]x[o, i, 0, 1, 2]->[b, o, 0, 1, 2]
      dimension_numbers = #stablehlo.conv<[
        b, i, 0, 1, 2
      ]x[
        o, i, 0, 1, 2
      ]->[
