  // Input:  %arg1: tensor<8x6x8x8x8xf32>  (N, C_in, D, H, W)
  // Weight: %arg0: tensor<6x7x3x3x3xf32>   (C_in, C_out, kD, kH, kW)
  // Output: tensor<8x7x10x10x10xf32>       (N, C_out, D_out, H_out, W_out)
  // PyTorch weight layout: (C_in, C_out, kD, kH, kW)
  // StableHLO expects:     (O, I, kD, kH, kW)
  // So we need to transpose weight dims [0,1,2,3,4] -> [1,0,2,3,4]
  // ConvTranspose3d is implemented as a convolution with swapped lhs/rhs, kernel flipped spatially, and appropriate dilation.

  func.func @main(%arg0: tensor<6x7x3x3x3xf32>, %arg1: tensor<8x6x8x8x8xf32>) -> tensor<8x7x10x10x10xf32> {
    // Transpose weight from (6,7,3,3,3) to (7,6,3,3,3)
    %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1,0,2,3,4>} : (tensor<6x7x3x3x3xf32>) -> tensor<7x6x3x3x3xf32>
