    %weight_flip = "stablehlo.reverse"(%weight_t) {dimensions = array<i64: 2,3,4>} : (tensor<7x6x3x3x3xf32>) -> tensor<7x6x3x3x3xf32>
    // Convolution: input (N, I, D, H, W), kernel (O, I, kD, kH, kW)
    // For transposed conv, swap lhs/rhs, set rhs_dilation = stride, padding = (kernel_size-1, kernel_size-1)
    // Here, stride=1, dilation=1, padding=0, output_padding=0, so rhs_dilation=1, lhs_dilation=1, window_strides=1, padding=2 on each side
    // For transposed conv, padding = kernel_size-1 - padding = 2-0 = 2
    // So, padding = [[2,2],[2,2],[2,2]] for D,H,W
    %result = "stablehlo.convolution"(%arg1, %weight_flip) {
      window_strides = array<i64: 1,1,1>,
      padding = dense<[[2,2],[2,2],[2,2]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1,1,1>,
      rhs_dilation = array<i64: 1,1,1>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64,
      // Corrected: dimension_numbers must use i (input feature), o (output feature)
      // Input:  (N, I, D, H, W)
      // Kernel: (O, I, kD, kH, kW)
      // Output: (N, O, D, H, W)
      dimension_numbers = #stablehlo.conv<[
        b, i, 0, 1, 2
      ]x[
        o, i, 0, 1, 2
      ]->[
        b, o, 0, 1, 2
      ]>
    } : (tensor<8x6x8x8x8xf32>, tensor<7x6x3x3x3xf32>) -> tensor<8x7x10x10x10xf32>
    return %result : tensor<8x7x10x10x10xf32>
  }
}
