func.func @main(
  %arg0: tensor<6x1x1xf32>,      // multiplier
  %arg1: tensor<6x6x3x3xf32>,    // conv.weight
  %arg2: tensor<6xf32>,          // conv.bias
  %arg3: tensor<6x6x7x7xf32>     // input
) -> tensor<6x6x5x5xf32> {
  // Convolution: input [N=6, C=6, H=7, W=7], weight [O=6, I=6, KH=3, KW=3]
  // Output: [N=6, O=6, H_out=5, W_out=5]
  // PyTorch default: NCHW, weight [O, I, KH, KW]
  // StableHLO: [N, C, H, W], [O, I, KH, KW], output [N, O, H, W]
  // Stride=1, Padding=0, Dilation=1

  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[
      b, f, 0, 1
    ]x[
      o, i, 0, 1
    ]->[
      b, o, 0, 1
    ]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<6x6x5x5xf32>

  // Add bias: bias shape [6], need to broadcast to [6,6,5,5] along axis 1 (output channels)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<6xf32>) -> tensor<6x6x5x5xf32>

  %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x6x5x5xf32>

  // Multiply by multiplier: multiplier shape [6,1,1], need to broadcast to [6,6,5,5] along axis 1,2,3
  %mult_bcast = "stablehlo.broadcast_in_dim"(%arg0) {
    broadcast_dimensions = array<i64: 1, 2, 3>
  } : (tensor<6x1x1xf32>) -> tensor<6x6x5x5xf32>

  %mul = stablehlo.multiply %conv_bias, %mult_bcast : tensor<6x6x5x5xf32>

  // LeakyReLU: x >= 0 ? x : 0.01 * x
  // 0.0 constant
  %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_zero_bcast = "stablehlo.broadcast_in_dim"(%cst_zero) {
    broadcast_dimensions = array<i64:>
  } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  // 0.01 constant
  %cst_alpha = stablehlo.constant dense<0.01> : tensor<f32>
  %cst_alpha_bcast = "stablehlo.broadcast_in_dim"(%cst_alpha) {
    broadcast_dimensions = array<i64:>
  } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  // pred: x >= 0
  %ge_pred = "stablehlo.compare"(%mul, %cst_zero_bcast) {
    comparison_direction = #stablehlo<comparison_direction GE>,
    compare_type = #stablehlo<comparison_type FLOAT>
  } : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xi1>
  // 0.01 * x
  %mul_alpha = stablehlo.multiply %mul, %cst_alpha_bcast : tensor<6x6x5x5xf32>
  // select
  %leaky = "stablehlo.select"(%ge_pred, %mul, %mul_alpha) : (tensor<6x6x5x5xi1>, tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // 0.5 constant
  %cst_half = stablehlo.constant dense<0.5> : tensor<f32>
  %cst_half_bcast = "stablehlo.broadcast_in_dim"(%cst_half) {
    broadcast_dimensions = array<i64:>
  } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  // 1.0 constant
  %cst_one = stablehlo.constant dense<1.0> : tensor<f32>
  %cst_one_bcast = "stablehlo.broadcast_in_dim"(%cst_one) {
    broadcast_dimensions = array<i64:>
  } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  // sqrt(2) constant
  %cst_sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>
  %cst_sqrt2_bcast = "stablehlo.broadcast_in_dim"(%cst_sqrt2) {
    broadcast_dimensions = array<i64:>
  } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  // x / sqrt(2)
  %div = stablehlo.divide %leaky, %cst_sqrt2_bcast : tensor<6x6x5x5xf32>
  // erf(x / sqrt(2))
  %erf = chlo.erf %div : tensor<6x6x5x5xf32> -> tensor<6x6x5x5xf32>
  // 1 + erf(...)
  %add1 = stablehlo.add %cst_one_bcast, %erf : tensor<6x6x5x5xf32>
  // x * (1 + erf(...))
  %mul2 = stablehlo.multiply %leaky, %add1 : tensor<6x6x5x5xf32>
  // 0.5 * ...
  %gelu = stablehlo.multiply %cst_half_bcast, %mul2 : tensor<6x6x5x5xf32>

  return %gelu : tensor<6x6x5x5xf32>
}
