  // Entry function
  func.func @main(
      %scale: tensor<1xf32>,           // scale parameter
      %gemm_weight: tensor<7x7xf32>,   // gemm.weight (out_features x in_features)
      %gemm_bias: tensor<7xf32>,       // gemm.bias (out_features)
      %bn_weight: tensor<7xf32>,       // bn.weight (out_features)
      %bn_bias: tensor<7xf32>,         // bn.bias (out_features)
      %input: tensor<6x7xf32>          // input (batch_size x in_features)
    ) -> tensor<6x7xf32> {
    // GEMM: y = x @ W^T + b
    // dot_general: lhs [batch, in_features], rhs [out_features, in_features] (need to transpose)
    // We want: [6,7] x [7,7]^T = [6,7] x [7,7] = [6,7]
    // But PyTorch Linear uses weight [out_features, in_features], so we need to transpose for matmul
    %gemm_weight_T = stablehlo.transpose(%gemm_weight, [1, 0]) : tensor<7x7xf32> to tensor<7x7xf32>
    %gemm = stablehlo.dot_general(
      %input, %gemm_weight_T,
      {
        // batch: [0], [0], contracting: [1], [1]
        // input: [batch, in_features], weight_T: [in_features, out_features]
        // result: [batch, out_features]
        dimension_numbers = [
          [ [1], [0] ], // contracting dims
          [ [0], [1] ]  // batch dims
        ],
        // No precision config
        precision_config = []
      }
    ) : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias (broadcast)
    %gemm_bias_bcast = stablehlo.broadcast_in_dim %gemm_bias, dims = [1] : (tensor<7xf32>) -> tensor<6x7xf32>
    %gemm_out = stablehlo.add(%gemm, %gemm_bias_bcast) : tensor<6x7xf32>

