    // Compute mean over batch (dim 0)
    %c0 = stablehlo.constant dense<0> : tensor<1xi32>
    %c1 = stablehlo.constant dense<1> : tensor<1xi32>
    %c6 = stablehlo.constant dense<6> : tensor<1xi32>
    %c7 = stablehlo.constant dense<7> : tensor<1xi32>
    %bn_eps = stablehlo.constant dense<1.0000000116860974E-5> : tensor<f32>
    // mean: reduce over dim 0 (batch)
    %mean = stablehlo.reduce(
      %gemm_out, 
