```mlir
func.func @main(
    %arg0: tensor<1xf32>,      // scale
    %arg1: tensor<7x7xf32>,    // gemm.weight
    %arg2: tensor<7xf32>,      // gemm.bias
    %arg3: tensor<7xf32>,      // bn.weight
    %arg4: tensor<7xf32>,      // bn.bias
    %arg5: tensor<6x7xf32>     // input x
) -> tensor<6x7xf32> {
  // GEMM: x @ W^T + b
  // Transpose weight to (7,7) -> (7,7) (no-op, but for generality)
  %wT = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // Dot: (6x7) @ (7x7) -> (6x7)
  %gemm = "stablehlo.dot_general"(%arg5, %wT) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Broadcast bias (7,) -> (6,7)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_bias = stablehlo.add %gemm, %bias_bcast : tensor<6x7xf32>

  // BatchNorm1d (training): y = (x - mean) / sqrt(var + eps) * weight + bias
  // Compute mean over batch (dim 0): (6x7) -> (7,)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gemm_bias, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // Divide by batch size (6)
  %c6 = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %c6 : tensor<7xf32>, tensor<f32> -> tensor<7xf32>
  // Broadcast mean to (6,7)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // x - mean
  %centered = stablehlo.subtract %gemm_bias, %mean_bcast : tensor<6x7xf32>
  // (x - mean)^2
  %centered2 = stablehlo.multiply %centered, %centered : tensor<6x7xf32>
  // Compute variance: mean of squared centered values over batch (dim 0)
  %var = "stablehlo.reduce"(%centered2, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var_div = stablehlo.divide %var, %c6 : tensor<7xf32>, tensor<f32> -> tensor<7xf32>
  // Add epsilon (1e-5)
  %eps = stablehlo.constant dense<1.0000000116860974E-5> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var_div, %eps_bcast : tensor<7xf32>
  // sqrt(var + eps)
  %std = stablehlo.sqrt %var_eps : tensor<7xf32>
  // Broadcast std to (6,7)
  %std_bcast = "stablehlo.broadcast_in_dim"(%std) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // Normalize: (x - mean) / sqrt(var + eps)
  %normed = stablehlo.divide %centered, %std_bcast : tensor<6x7xf32>
  // Broadcast bn.weight and bn.bias to (6,7)
  %bnw_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bnb_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // y = normed * weight + bias
  %bn_mul = stablehlo.multiply %normed, %bnw_bcast : tensor<6x7xf32>
  %bn_out = stablehlo.add %bn_mul, %bnb_bcast : tensor<6x7xf32>

  // Scale: scale is (1,) -> broadcast to (6,7)
  %scale_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: >} : (tensor<1xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %scale_bcast, %bn_out : tensor<6x7xf32>

  // Softmax along dim=1 (features)
  // For numerical stability, subtract max along dim=1
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>
  // max along dim=1 (features): (6x7) -> (6,)
  %max = "stablehlo.reduce"(%scaled, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %m = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%m) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast max to (6,7)
  %max_bcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>
  %shifted = stablehlo.subtract %scaled, %max_bcast : tensor<6x7xf32>
  // exp
  %exp = stablehlo.exponential %shifted : tensor<6x7xf32>
  // sum along dim=1 (features): (6x7) -> (6,)
  %sum_init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%exp, %sum_init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
