module {
  // Entry function: performs 3D convolution with asymmetric kernel (3,5,7), no bias, stride=1, padding=0, dilation=1, groups=1.
  // %arg0: conv3d.weight, shape [8,3,3,5,7] (out_c, in_c, kW, kH, kD)
  // %arg1: input, shape [16,3,8,8,8] (N, in_c, W, H, D)
  // Output: [16,8,6,4,2] (N, out_c, W_out, H_out, D_out)
  func.func @main(
    %arg0: tensor<8x3x3x5x7xf32>,   // weight
    %arg1: tensor<16x3x8x8x8xf32>   // input
  ) -> tensor<16x8x6x4x2xf32> {
    // StableHLO expects input as [N, spatial..., C], but PyTorch is [N, C, W, H, D].
    // We'll transpose input and weights to match StableHLO's [N, D, H, W, C] and [O, D, H, W, I] conventions.

    // Transpose input: [N, C, W, H, D] -> [N, D, H, W, C]
    %input_t = stablehlo.transpose(%arg1, [0, 4, 3, 2, 1]) : (tensor<16x3x8x8x8xf32>) -> tensor<16x8x8x8x3xf32>
    // Transpose weight: [O, I, kW, kH, kD] -> [O, kD, kH, kW, I]
    %weight_t = stablehlo.transpose(%arg0, [0, 4, 3, 2, 1]) : (tensor<8x3x3x5x7xf32>) -> tensor<8x7x5x3x3xf32>

    // Convolution: input [N, D, H, W, C], filter [O, kD, kH, kW, I]
    // window_strides = [1,1,1], padding = [0,0,0,0,0,0], lhs_dilation = [1,1,1], rhs_dilation = [1,1,1]
    // feature_group_count = 1, batch_group_count = 1
    // dimension_numbers: lhs=[N, D, H, W, C], rhs=[O, kD, kH, kW, I], out=[N, D, H, W, O]
    %conv = stablehlo.convolution(
      %input_t, %weight_t,
      window_strides = [1, 1, 1],
      padding = [0, 0, 0, 0, 0, 0],
      lhs_dilation = [1, 1, 1],
      rhs_dilation = [1, 1, 1],
      feature_group_count = 1,
      batch_group_count = 1,
      dimension_numbers = #stablehlo.conv_dimension_numbers<
        input_batch_dimension = 0,
        input_feature_dimension = 4,
        input_spatial_dimensions = [1, 2, 3],
        kernel_output_feature_dimension = 0,
        kernel_input_feature_dimension = 4,
        kernel_spatial_dimensions = [1, 2, 3],
        output_batch_dimension = 0,
        output_feature_dimension = 4,
        output_spatial_dimensions = [1, 2, 3]
      >
    ) : (tensor<16x8x8x8x3xf32>, tensor<8x7x5x3x3xf32>) -> tensor<16x2x4x6x8xf32>

    // Output is [N, D_out, H_out, W_out, O], but we want [N, O, W_out, H_out, D_out] = [16,8,6,4,2]
    // So, transpose: [0, 4, 3, 2, 1]
    %out = stablehlo.transpose(%conv, [0, 4, 3, 2, 1]) : (tensor<16x2x4x6x8xf32>) -> tensor<16x8x6x4x2xf32>
    return %out : tensor<16x8x6x4x2xf32>
  }
}
