module {
  // Entry function
  func.func @main(
    %arg0: tensor<7x7x3x3xf32>,   // conv_transpose.weight [out_c, in_c, kH, kW]
    %arg1: tensor<7xf32>,         // conv_transpose.bias   [out_c]
    %arg2: tensor<6x7x8x8xf32>    // input [N, in_c, H, W]
  ) -> tensor<6x7x1x1xf32> {
    // 1. Transposed convolution (ConvTranspose2d)
    // PyTorch: [N, in_c, H, W] x [in_c, out_c, kH, kW] -> [N, out_c, H, W]
    // StableHLO convolution is not transposed, so we simulate ConvTranspose2d by
    // swapping lhs/rhs and using rhs_dilation.

    // For ConvTranspose2d with stride=1, padding=1, kernel=3, output_padding=0:
    // - Use rhs_dilation = [1,1] (no dilation)
    // - Use padding = [[1,1],[1,1]]
    // - Use dimension_numbers: [N, in_c, H, W] x [out_c, in_c, kH, kW] -> [N, out_c, H, W]
    // But for transposed, we swap in_c/out_c in the kernel and use lhs_dilation.

    // So, for ConvTranspose2d:
    // - lhs = input: [N, in_c, H, W]
    // - rhs = weight: [in_c, out_c, kH, kW]
    // - lhs_dilation = [1,1]
    // - rhs_dilation = [1,1]
    // - window_strides = [1,1]
    // - padding = [[1,1],[1,1]]
    // - dimension_numbers = [N, in_c, H, W] x [in_c, out_c, kH, kW] -> [N, out_c, H, W]
    // But StableHLO expects [N, in_c, H, W] x [out_c, in_c, kH, kW] -> [N, out_c, H, W]
    // So we need to transpose the weight.

    // Transpose weight from [out_c, in_c, kH, kW] to [in_c, out_c, kH, kW]
    %weight_t = stablehlo.transpose %arg0, [1, 0, 2, 3] : tensor<7x7x3x3xf32> to tensor<7x7x3x3xf32>

    // Convolution: [N, in_c, H, W] x [in_c, out_c, kH, kW] -> [N, out_c, H, W]
    %conv = "stablehlo.convolution"(%arg2, %weight_t) {
      window_strides = dense<[1, 1]> : tensor<2xi64>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64,
      dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[1, 0, 2, 3]->[0, 1, 2, 3]>
    } : (tensor<6x7x8x8xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x8x8xf32>

    // Add bias: [N, out_c, H, W] + [out_c] (broadcast)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = dense<[1]> : tensor<1xi64>
    } : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %bias_bcast2 = "stablehlo.broadcast_in_dim"(%bias_bcast) {
      broadcast_dimensions = dense<[0,1,2,3]> : tensor<4xi64>
    } : (tensor<1x7x1x1xf32>) -> tensor<6x7x8x8xf32>
    %conv_bias = stablehlo.add %conv, %bias_bcast2 : tensor<6x7x8x8xf32>

    // 2. MaxPool2d(kernel=2, stride=2)
    // ReduceWindow with window_dimensions=[1,1,2,2], window_strides=[1,1,2,2], padding=0
    %neg_inf = stablehlo.constant dense<-3.4028235e+38> : tensor<f32>
    %maxpool = "stablehlo.reduce_window"(%conv_bias, %neg_inf) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %max = stablehlo.maximum %a, %b : tensor<f32>
        stablehlo.return %max : tensor<f32>
    }) {
      window_dimensions = dense<[1, 1, 2, 2]> : tensor<4xi64>,
      window_strides = dense<[1, 1, 2, 2]> : tensor<4xi64>,
      padding = dense<[[0,0],[0,0],[0,0],[0,0]]> : tensor<4x2xi64>
    } : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

    // 3. Hardtanh(min=-1, max=1): clamp between -1 and 1
    %min1 = stablehlo.constant dense<-1.0> : tensor<f32>
    %plus1 = stablehlo.constant dense<1.0> : tensor<f32>
    %min_bcast = "stablehlo.broadcast_in_dim"(%min1) {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %max_bcast = "stablehlo.broadcast_in_dim"(%plus1) {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %clamped = stablehlo.maximum %maxpool, %min_bcast : tensor<6x7x4x4xf32>
    %clamped2 = stablehlo.minimum %clamped, %max_bcast : tensor<6x7x4x4xf32>

    // 4. Mean over (2,3) (spatial), keepdim=True
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %sum = "stablehlo.reduce"(%clamped2, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %s : tensor<f32>
    }) {dimensions = dense<[2,3]> : tensor<2xi64>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x1x1xf32>
    %divisor = stablehlo.constant dense<16.0> : tensor<f32>
    %divisor_bcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x7x1x1xf32>
    %mean = stablehlo.divide %sum, %divisor_bcast : tensor<6x7x1x1xf32>

    // 5. Tanh activation
    %out = stablehlo.tanh %mean : tensor<6x7x1x1xf32>

    return %out : tensor<6x7x1x1xf32>
  }
}
