func.func @main(
  %bmm_weight: tensor<7x7xf32>,   // arg0: bmm.weight
  %bmm_bias: tensor<7xf32>,       // arg1: bmm.bias
  %x: tensor<6x7xf32>,            // arg2: input x
  %y: tensor<6x7xf32>             // arg3: input y
) -> tensor<6x7xf32> {
  // Linear: x @ W^T + b
  // x: [6,7], bmm_weight: [7,7] (out_features, in_features)
  // PyTorch Linear: y = x @ W^T + b
  // So we need to dot x [6,7] with bmm_weight^T [7,7] -> [6,7]
  %bmm_weight_t = "stablehlo.transpose"(%bmm_weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %x_bmm = "stablehlo.dot_general"(%x, %bmm_weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast b to [6,7]
  %bmm_bias_bcast = "stablehlo.broadcast_in_dim"(%bmm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_bmm_bias = stablehlo.add %x_bmm, %bmm_bias_bcast : tensor<6x7xf32>

  // InstanceNorm2d: on shape [N, C, H, W] = [6,7,1,1]
  // Reshape to [6,7,1,1]
  %x_4d = stablehlo.reshape %x_bmm_bias : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
  // Compute mean over [2,3] (H,W)
  // mean = sum(x, dims=[2,3]) / (1*1) = just x itself, but keep dims
  // For generality, do the reduction
