    // Add epsilon
    %epsilon = stablehlo.constant dense<1.0000000116860974E-5> : tensor<f32>
    %epsilon_bcast = stablehlo.broadcast_in_dim %epsilon, [] : (tensor<f32>) -> tensor<6x7x1x1xf32>
