    %bmm_bias: tensor<7xf32>,       // arg1: nn.Linear bias, shape (out_features)
    %x: tensor<6x7xf32>,            // arg2: input x, shape (batch_size, in_features)
    %y: tensor<6x7xf32>             // arg3: input y, shape (batch_size, out_features)
  ) -> tensor<6x7xf32> {
    // 1. Linear: x @ bmm_weight^T + bmm_bias
    // x: (6,7), bmm_weight: (7,7) (out,in), want x @ bmm_weight^T
    // dot_general: lhs_contracting=[1], rhs_contracting=[0]
    %linear = "stablehlo.dot_general"(%x, %bmm_weight) {
      dot_dimension_numbers = #stablehlo.dot<
        lhs_contracting_dimensions = [1],
        rhs_contracting_dimensions = [1]
      >
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias: bmm_bias (7,) -> (6,7)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%bmm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %linear_bias = stablehlo.add %linear, %bias_broadcast : tensor<6x7xf32>

    // 2. InstanceNorm2d: on (6,7) as (N,C,H,W) = (6,7,1,1)
    // Reshape to (6,7,1,1)
    %inorm_reshape = stablehlo.reshape %linear_bias : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
    // Compute mean over (2,3) (H,W)
    // mean = sum / N
    // Reduce sum over dims 2,3
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %sum_hw = "stablehlo.reduce"(%inorm_reshape, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
    // mean = sum_hw / 1 (since H=W=1), so mean = sum_hw
    %mean = %sum_hw

