    %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0,1>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
    %centered = stablehlo.subtract %inorm_reshape, %mean_broadcast : tensor<6x7x1x1xf32>

