    %weight_t = "stablehlo.transpose"(%bmm_weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // dot_general: lhs [6,7], rhs [7,7], contracting dim 1 (lhs) with dim 0 (rhs)
    %linear = "stablehlo.dot_general"(%x, %weight_t) {
      lhs_batching_dimensions = dense<[]> : tensor<0xi64>,
      rhs_batching_dimensions = dense<[]> : tensor<0xi64>,
      lhs_contracting_dimensions = dense<[1]> : tensor<1xi64>,
      rhs_contracting_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias: [6,7] + [7] (broadcast)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%bmm_bias) {broadcast_dimensions = array<i64: 1}, shape = dense<[6,7]> : tensor<2xi64>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %linear_bias = "stablehlo.add"(%linear, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // 2. InstanceNorm2d: on shape [N,C,H,W] with C=7, H=1, W=1
    // Reshape to [6,7,1,1]
    %x4d = "stablehlo.reshape"(%linear_bias) : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
    // Compute mean over [2,3] (H,W)
    // But H=W=1, so mean is just the value itself; but InstanceNorm2d still normalizes per-instance, per-channel
    // So mean/var over [2,3] for each [N,C]
    // Reduce mean: axes [2,3]
    %mean = "stablehlo.reduce"(%x4d, %zero) ({
      ^bb0(%a: f32, %b: f32):
        %add = "stablehlo.add"(%a, %b) : (f32, f32) -> f32
        "stablehlo.return"(%add) : (f32) -> ()
    }) {dimensions = dense<[2,3]> : tensor<2xi64>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
    // Divide by count (H*W=1*1=1, so skip division)
    // Broadcast mean to [6,7,1,1]
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0,1}, shape = dense<[6,7,1,1]> : tensor<4xi64>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
    // x - mean
