    // Variance: mean((x - mean)^2) over [2,3]
    %centered_sq = "stablehlo.multiply"(%centered, %centered) : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>
    %var = "stablehlo.reduce"(%centered_sq, %zero) ({
      ^bb0(%a: f32, %b: f32):
        %add = "stablehlo.add"(%a, %b) : (f32, f32) -> f32
        "stablehlo.return"(%add) : (f32) -> ()
    }) {dimensions = dense<[2,3]> : tensor<2xi64>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
    // No division needed (H*W=1)
    // Broadcast var to [6,7,1,1]
    %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0,1}, shape = dense<[6,7,1,1]> : tensor<4xi64>} : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
    // Add epsilon
    %eps = "stablehlo.constant"() {value = dense<1.0000000116860974E-5> : tensor<f32>} : () -> tensor<f32>
    %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >, shape = dense<[6,7,1,1]> : tensor<4xi64>} : (tensor<f32>) -> tensor<6x7x1x1xf32>
    %var_eps = "stablehlo.add"(%var_bcast, %eps_bcast) : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>
    // sqrt(var + eps)
    %std = "stablehlo.sqrt"(%var_eps) : (tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>
    // Normalize
