    // 3. Add y: [6,7] + [6,7]
    %add = "stablehlo.add"(%normed2d, %y) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // 4. Multiply by y: [6,7] * [6,7]
    %mul = "stablehlo.multiply"(%add, %y) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Return
