module {
  // Entry function
  func.func @main(
      %bmm_weight: tensor<7x7xf32>,   // Linear weight: [out_features, in_features]
      %bmm_bias: tensor<7xf32>,       // Linear bias: [out_features]
      %x: tensor<6x7xf32>,            // Input x: [batch, in_features]
      %y: tensor<6x7xf32>             // Input y: [batch, out_features]
    ) -> tensor<6x7xf32> {
    // ---- Linear: x @ W^T + b ----
    // PyTorch Linear: y = x @ W^T + b
    // x: [6,7], W: [7,7] (out,in), so W^T: [7,7]
    // dot_general: lhs: [6,7], rhs: [7,7], contracting [1] with [1] (in_features)
    %0 = stablehlo.dot_general
      %x, %bmm_weight,
      {
        lhs_contracting_dimensions = dense<1> : tensor<1xi64>,
        rhs_contracting_dimensions = dense<1> : tensor<1xi64>,
        lhs_batch_dimensions = dense<> : tensor<0xi64>,
        rhs_batch_dimensions = dense<> : tensor<0xi64>
      }
      : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias: [7] -> [6,7]
    %1 = stablehlo.broadcast_in_dim %bmm_bias, dims = [1] : (tensor<7xf32>) -> tensor<6x7xf32>
    %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

    // ---- InstanceNorm2d ----
    // InstanceNorm2d on shape [batch, C, H, W] with C=7, H=1, W=1
    // PyTorch: x.unsqueeze(1).unsqueeze(1) -> [6,7] -> [6,7,1,1]
    %3 = stablehlo.reshape %2 : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

    // Compute mean over [2,3] (H,W) for each [batch,channel]
    // Since H=W=1, mean is just the value itself, but we follow the reduction for generality.
    // mean: reduce over dims [2,3]
    %c0 = stablehlo.constant dense<0.0> : tensor<f32>
    %4 = stablehlo.reduce
      %3, %c0
      dimensions = [2, 3]
      to_apply = @add_f32
      : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
    // Divide by (H*W) = 1, so skip division

    // mean: [6,7] -> [6,7,1,1]
    %5 = stablehlo.reshape %4 : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

    // Subtract mean
    %6 = stablehlo.subtract %3, %5 : tensor<6x7x1x1xf32>

    // Compute variance: mean((x - mean)^2) over [2,3]
    %7 = stablehlo.multiply %6, %6 : tensor<6x7x1x1xf32>
    %8 = stablehlo.reduce
      %7, %c0
      dimensions = [2, 3]
      to_apply = @add_f32
      : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
    // Divide by (H*W) = 1, so skip division

    // variance: [6,7] -> [6,7,1,1]
    %9 = stablehlo.reshape %8 : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

    // Add eps (1e-5) for numerical stability
    %eps = stablehlo.constant dense<1.0000000116860974E-5> : tensor<f32>
    %10 = stablehlo.broadcast_in_dim %eps, dims = [] : (tensor<f32>) -> tensor<6x7x1x1xf32>
    %11 = stablehlo.add %9, %10 : tensor<6x7x1x1xf32>

    // Compute rsqrt(variance + eps)
    %12 = stablehlo.rsqrt %11 : tensor<6x7x1x1xf32>

    // Normalize: (x - mean) * rsqrt(var + eps)
    %13 = stablehlo.multiply %6, %12 : tensor<6x7x1x1xf32>

    // Squeeze to [6,7]
    %14 = stablehlo.reshape %13 : (tensor<6x7x1x1xf32>) -> tensor<6x7xf32>

    // ---- Add y ----
    %15 = stablehlo.add %14, %y : tensor<6x7xf32>

    // ---- Multiply by y ----
    %16 = stablehlo.multiply %15, %y : tensor<6x7xf32>

    // Return
    return %16 : tensor<6x7xf32>
  }

  // Addition reduction for mean/variance
  func.func private @add_f32(%a: tensor<f32>, %b: tensor<f32>) -> tensor<f32> {
    %0 = stablehlo.add %a, %b : tensor<f32>
    return %0 : tensor<f32>
  }
}
