module {
  func.func @main(
    %weight: tensor<7x7xf32>, 
    %bias: tensor<7xf32>, 
    %input: tensor<6x7xf32>
  ) -> tensor<6x7xf32> {
    // Linear: y = x @ W^T + b
    // Transpose weight to shape [7,7] -> [7,7] (no-op, but for clarity)
    %weight_t = "stablehlo.transpose"(%weight) {permutation = dense<[1, 0]> : tensor<2xi64>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // Dot general: [6,7] x [7,7] -> [6,7]
    %linear = "stablehlo.dot_general"(%input, %weight_t) {
      dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0], lhs_batch_dimensions = [], rhs_batch_dimensions = []>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Broadcast bias [7] to [6,7]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %linear_bias = "stablehlo.add"(%linear, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Mish(x) = x * tanh(softplus(x)), softplus(x) = log(1 + exp(x))
    // First Mish
    // exp(x)
    %exp1 = "stablehlo.exponential"(%linear_bias) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // constant 1.0
    %cst1 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %cst1_bcast = "stablehlo.broadcast_in_dim"(%cst1) {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x7xf32>
    // 1 + exp(x)
    %exp1_plus1 = "stablehlo.add"(%exp1, %cst1_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // log(1 + exp(x))
    %softplus1 = "stablehlo.log"(%exp1_plus1) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // tanh(softplus(x))
    %tanh1 = "stablehlo.tanh"(%softplus1) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // x * tanh(softplus(x))
    %mish1 = "stablehlo.multiply"(%linear_bias, %tanh1) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Second Mish
    %exp2 = "stablehlo.exponential"(%mish1) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %exp2_plus1 = "stablehlo.add"(%exp2, %cst1_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %softplus2 = "stablehlo.log"(%exp2_plus1) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %tanh2 = "stablehlo.tanh"(%softplus2) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %mish2 = "stablehlo.multiply"(%mish1, %tanh2) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    return %mish2 : tensor<6x7xf32>
  }
}
