    // Add bias: broadcast bias [7] to [6,7]
    %2 = stablehlo.broadcast_in_dim(%arg1, dims = [1]) : (tensor<7xf32>) -> tensor<6x7xf32>
    %3 = stablehlo.add(%1, %2) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Swish: x * sigmoid(x)
    %4 = stablehlo.logistic(%3) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %5 = stablehlo.multiply(%3, %4) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Divide by 2.0
