    %6 = stablehlo.broadcast_in_dim(%cst_2, dims = []) : (tensor<f32>) -> tensor<6x7xf32>
    %7 = stablehlo.divide(%5, %6) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Clamp between -1.0 and 1.0
    %cst_min1 = stablehlo.constant dense<-1.0> : tensor<f32>
    %cst_p1 = stablehlo.constant dense<1.0> : tensor<f32>
