    %10 = stablehlo.maximum(%7, %8) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %11 = stablehlo.minimum(%10, %9) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Tanh
