module {
  func.func @main(
    %bias: tensor<1x1x1x1xf32>, 
    %weight: tensor<3x16x3x3x3xf32>, 
    %conv_bias: tensor<16xf32>, 
    %input: tensor<6x3x16x7x7xf32>
  ) -> tensor<6x1x31x13x13xf32> {
    // 1. ConvTranspose3d (input: N,Cin,D,H,W; weight: Cin,Cout,Kd,Kh,Kw)
    // PyTorch: out = stride=2, padding=1, kernel=3, bias=conv_bias
    // StableHLO: convolution with swapped in/out channels, rhs_dilation=1, lhs_dilation=1, window_strides=2, padding=1
    // PyTorch weight: (Cin, Cout, Kd, Kh, Kw) -> StableHLO: (Cout, Cin, Kd, Kh, Kw)
    // So, transpose weight [1,0,2,3,4]
    %weight_t = "stablehlo.transpose"(%weight) {permutation = dense<[1,0,2,3,4]> : tensor<5xi64>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>
    // Convolution dimension_numbers: [N, C, D, H, W] x [O, I, kD, kH, kW] -> [N, O, D, H, W]
    %conv = "stablehlo.convolution"(%input, %weight_t) {
      window_strides = array<i64: 2, 2, 2>,
      padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
      rhs_dilation = array<i64: 1, 1, 1>,
      dimension_numbers = #stablehlo.conv<[
        b, f, 0, 1, 2
      ]x[
        o, i, 0, 1, 2
      ]->[
        b, o, 0, 1, 2
      ]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x31x13x13xf32>
    // Add conv_bias (shape [16]) to channel dim (dim=1)
    %conv_bias_b = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<6x16x31x13x13xf32>
    %conv_out = stablehlo.add %conv, %conv_bias_b : tensor<6x16x31x13x13xf32>
    // 2. logsumexp over channel dim=1, keepdim=True
    // logsumexp(x, dim=1, keepdim=True) = log(reduce_sum(exp(x), dim=1, keepdim=True))
    %exp = stablehlo.exponential %conv_out : tensor<6x16x31x13x13xf32>
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %sum = "stablehlo.reduce"(%exp, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x1x31x13x13xf32>
    %log = stablehlo.log %sum : tensor<6x1x31x13x13xf32>
