module {
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  func.func private @gelu(%x: tensor<16x16xf32>) -> tensor<16x16xf32> {
    %cst_0_5 = stablehlo.constant dense<0.5> : tensor<f32>
    %cst_1 = stablehlo.constant dense<1.0> : tensor<f32>
    %cst_sqrt2 = stablehlo.constant dense<1.41421354> : tensor<f32>
    // x / sqrt(2)
    %sqrt2_bcast = stablehlo.broadcast_in_dim %cst_sqrt2, dims = [] : (tensor<f32>) -> tensor<16x16xf32>
    %x_div_sqrt2 = stablehlo.divide %x, %sqrt2_bcast : tensor<16x16xf32>
    // erf(x / sqrt(2))
    %erf = chlo.erf %x_div_sqrt2 : tensor<16x16xf32>
    // 1 + erf(...)
    %one_bcast = stablehlo.broadcast_in_dim %cst_1, dims = [] : (tensor<f32>) -> tensor<16x16xf32>
    %erf_plus_1 = stablehlo.add %one_bcast, %erf : tensor<16x16xf32>
    // x * (1 + erf(...))
    %x_times = stablehlo.multiply %x, %erf_plus_1 : tensor<16x16xf32>
    // 0.5 * ...
    %half_bcast = stablehlo.broadcast_in_dim %cst_0_5, dims = [] : (tensor<f32>) -> tensor<16x16xf32>
    %gelu = stablehlo.multiply %half_bcast, %x_times : tensor<16x16xf32>
    return %gelu : tensor<16x16xf32>
  }

  // Main function
  func.func @main(
    %matmul_weight: tensor<16x16xf32>,
    %matmul_bias: tensor<16xf32>,
    %input: tensor<16x16xf32>
  ) -> tensor<16xf32> {
    // Linear: x @ W^T + b
    // Transpose weight to (in_features, out_features) -> (out_features, in_features)
    %weight_t = stablehlo.transpose %matmul_weight, [1, 0] : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // Dot: (16,16) x (16,16) -> (16,16)
    %linear = stablehlo.dot_general %input, %weight_t {
      dot_dimension_numbers = #stablehlo.dot<
        lhs_contracting_dimensions = [1],
        rhs_contracting_dimensions = [0]
      >
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Bias: broadcast and add
    %bias_bcast = stablehlo.broadcast_in_dim %matmul_bias, dims = [1] : (tensor<16xf32>) -> tensor<16x16xf32>
    %linear_bias = stablehlo.add %linear, %bias_bcast : tensor<16x16xf32>

    // AvgPool1d with kernel=16, stride=16, no padding, input shape (16,16)
    // PyTorch's AvgPool1d on (B, C, L) with kernel=L, stride=L, returns (B, C, 1)
    // Here, input is (B, L), so we treat as (B, 1, L), pool over L, then squeeze.
    // Reshape to (16,1,16)
    %reshape1 = stablehlo.reshape %linear_bias : (tensor<16x16xf32>) -> tensor<16x1x16xf32>
    // Reduce_window: window=16, stride=16, no padding, reduce over dim 2 (L)
    %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
