      window_dimensions = dense<[1,1,16]> : tensor<3xi64>,
      window_strides = dense<[1,1,16]> : tensor<3xi64>,
      base_dilations = dense<[1,1,1]> : tensor<3xi64>,
      window_dilations = dense<[1,1,1]> : tensor<3xi64>,
      padding = dense<[[0,0],[0,0],[0,0]]> : tensor<3x2xi64>
    }, @add_f32 : (tensor<16x1x16xf32>, tensor<f32>) -> tensor<16x1x1xf32>
    // Divide by 16 for average
    %cst_16 = stablehlo.constant dense<16.0> : tensor<f32>
    %cst_16_bcast = stablehlo.broadcast_in_dim %cst_16, dims = [] : (tensor<f32>) -> tensor<16x1x1xf32>
