  %c16_bcast = "stablehlo.broadcast_in_dim"(%c16) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<f32>) -> tensor<16x1x1xf32>
  %avg = stablehlo.divide %sum, %c16_bcast : tensor<16x1x1xf32>

