  %squeezed = "stablehlo.reshape"(%avg) : (tensor<16x1x1xf32>) -> tensor<16x1xf32>

  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  %c05 = stablehlo.constant dense<0.5> : tensor<f32>
  %c05_bcast = "stablehlo.broadcast_in_dim"(%c05) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x1xf32>
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>
  %c1_bcast = "stablehlo.broadcast_in_dim"(%c1) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x1xf32>
