  %erf1 = stablehlo.add %c1_bcast, %erf : tensor<16x1xf32>
  %mul1 = stablehlo.multiply %squeezed, %erf1 : tensor<16x1xf32>
  %gelu = stablehlo.multiply %c05_bcast, %mul1 : tensor<16x1xf32>

