  %c2 = stablehlo.constant dense<2.0> : tensor<f32>
  %c2_bcast = "stablehlo.broadcast_in_dim"(%c2) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x1xf32>
  %scaled = stablehlo.multiply %gelu, %c2_bcast : tensor<16x1xf32>

