  // Use the minimum representable float32 value for -inf
  %c_minf = stablehlo.constant dense<-3.4028235E+38> : tensor<f32>
  %max = "stablehlo.reduce"(%scaled, %c_minf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %m = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %m : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<16x1xf32>, tensor<f32>) -> tensor<16xf32>

  return %max : tensor<16xf32>
}
