func.func @main(
    %arg0: tensor<8x8x3x3xf32>,   // conv_transpose.weight [in_c, out_c, kH, kW]
    %arg1: tensor<8xf32>,         // conv_transpose.bias   [out_c]
    %arg2: tensor<8xf32>,         // group_norm.weight     [out_c]
    %arg3: tensor<8xf32>,         // group_norm.bias       [out_c]
