  %eps = stablehlo.constant dense<1.0000001E-5> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<8x8xf32>
  %var_eps_bcast = "stablehlo.broadcast_in_dim"(%var_eps) {broadcast_dimensions = array<i64: 0,1>} : (tensor<8x8xf32>) -> tensor<8x8x10x10xf32>
  %std = stablehlo.sqrt %var_eps_bcast : tensor<8x8x10x10xf32>
  // Normalize
  %normed = stablehlo.divide %centered, %std : tensor<8x8x10x10xf32>
  // Apply scale and bias: group_norm.weight/bias [8] -> [8,8,10,10] along axis 1
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<8xf32>) -> tensor<8x8x10x10xf32>
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<8xf32>) -> tensor<8x8x10x10xf32>
  %normed_scaled = stablehlo.multiply %normed, %gn_weight_bcast : tensor<8x8x10x10xf32>
  %normed_shifted = stablehlo.add %normed_scaled, %gn_bias_bcast : tensor<8x8x10x10xf32>
  return %normed_shifted : tensor<8x8x10x10xf32>
}
