module {
  func.func @main(
    %matmul_weight: tensor<16x16xf32>, 
    %matmul_bias: tensor<16xf32>, 
    %input: tensor<16x16xf32>
  ) -> tensor<16xf32> {
    // Matmul: x @ W^T + b
    // Transpose weight to (in_features, out_features) -> (out_features, in_features)
    %weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // Dot: (batch, in_features) x (in_features, out_features) -> (batch, out_features)
    %matmul = "stablehlo.dot_general"(
      %input, %weight_t
    ) {
      lhs_batching_dimensions = dense<0> : tensor<1xi64>,
      rhs_batching_dimensions = dense<> : tensor<0xi64>,
      lhs_contracting_dimensions = dense<1> : tensor<1xi64>,
      rhs_contracting_dimensions = dense<1> : tensor<1xi64>
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Bias add: broadcast bias (16,) to (16,16)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%matmul_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %matmul_bias = "stablehlo.add"(%matmul, %bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // AvgPool1d: kernel=16, stride=16, input (batch, features)
    // Reshape to (batch, 1, features) for 1d pooling
    %pool_in = "stablehlo.reshape"(%matmul_bias) : (tensor<16x16xf32>) -> tensor<16x1x16xf32>
    // Reduce_window with window=16, stride=16, dims=[2] (features)
    // Initial value for sum: 0.0
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // Window sum
    %window_sum = "stablehlo.reduce_window"(%pool_in, %zero) {
      window_dimensions = dense<[1,1,16]> : tensor<3xi64>,
      window_strides = dense<[1,1,16]> : tensor<3xi64>,
      base_dilations = dense<[1,1,1]> : tensor<3xi64>,
      window_dilations = dense<[1,1,1]> : tensor<3xi64>,
      padding = dense<[[0,0],[0,0],[0,0]]> : tensor<3x2xi64>
    } ( ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%sum) : (tensor<f32>) -> ()
      ) : (tensor<16x1x16xf32>, tensor<f32>) -> tensor<16x1x1xf32>
    // Divide by 16.0 for average
    %inv16 = "stablehlo.constant"() {value = dense<0.0625> : tensor<f32>} : () -> tensor<f32>
    %window_sum_squeezed = "stablehlo.reshape"(%window_sum) : (tensor<16x1x1xf32>) -> tensor<16x1xf32>
    %avgpool = "stablehlo.multiply"(%window_sum_squeezed, %inv16) : (tensor<16x1xf32>, tensor<f32>) -> tensor<16x1xf32>
    // Squeeze to (16,16)
    %avgpool_squeezed = "stablehlo.reshape"(%avgpool) : (tensor<16x1xf32>) -> tensor<16xf32>
    // But we want (16,16): actually, after pooling, shape is (16,1,1), so we need to broadcast back to (16,16)
    // Actually, after pooling, each batch gets a single vector of length 1 (mean over features), but PyTorch's AvgPool1d with kernel=16 on (B,1,16) returns (B,1,1)
    // But in the code, after unsqueeze/squeeze, shape is (B, features) -> (B,1,features) -> pool -> (B,1,1) -> squeeze -> (B,1)
    // But in the PyTorch code, after squeeze(1), shape is (B,1)
    // But then gelu, scale, max over dim=1 (which is now singleton), so output is (B,)
    // But in the signature, output is (16,)
    // But in the StableHLO signature, output is (16xf32)
    // So, continue with (16,1) shape
    // GELU: y = 0.5 * x * (1 + erf(x / sqrt(2)))
    %sqrt2 = "stablehlo.constant"() {value = dense<1.4142135> : tensor<f32>} : () -> tensor<f32>
    %div = "stablehlo.divide"(%avgpool_squeezed, %sqrt2) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
    %erf = "stablehlo.erf"(%div) : (tensor<16xf32>) -> tensor<16xf32>
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    %erf_plus1 = "stablehlo.add"(%erf, %one) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
    %gelu_inner = "stablehlo.multiply"(%avgpool_squeezed, %erf_plus1) : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>
    %gelu = "stablehlo.multiply"(%gelu_inner, %half) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
    // Scale: *2.0
    %scale = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
    %scaled = "stablehlo.multiply"(%gelu, %scale) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
    // Max over dim=1 (features), input is (16,): but after all above, shape is (16,)
    // But in PyTorch, after max(dim=1), output is (batch,)
    // But in StableHLO, input is (16,), so just return as is
    // But if input is (16,16), need to reduce over axis 1
    // But our pipeline has reduced to (16,) already
    // So, just return
    return %scaled : tensor<16xf32>
  }
}
