module {
  // Entry function:
  // %arg0: matmul.weight (16x16xf32)
  // %arg1: matmul.bias   (16xf32)
  // %arg2: input x       (16x16xf32)
  //
  // Implements:
  //   x = matmul(x, weight^T) + bias
  //   x = avg_pool1d(x.unsqueeze(1), kernel_size=16).squeeze(1)
  //   x = GELU(x)
  //   x = x * 2.0
  //   x = torch.max(x, dim=1).values

  func.func @main(
    %weight: tensor<16x16xf32>,   // matmul.weight
    %bias: tensor<16xf32>,        // matmul.bias
    %x: tensor<16x16xf32>         // input
  ) -> tensor<16xf32> {
    // Matmul: x @ weight^T + bias
    // x:      [16,16]
    // weight: [16,16] (PyTorch Linear: out_features x in_features)
    // We want: x [B, in_features] @ weight.T [in_features, out_features]
    //         = [B, out_features]
    // So: dot_general with lhs_contracting_dim=1, rhs_contracting_dim=1

    %0 = stablehlo.dot_general
      %x, %weight,
      {
        lhs_contracting_dimensions = dense<1> : tensor<1xi64>,
        rhs_contracting_dimensions = dense<1> : tensor<1xi64>,
        lhs_batching_dimensions = dense<> : tensor<0xi64>,
        rhs_batching_dimensions = dense<> : tensor<0xi64>
      }
      : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Add bias: bias shape [16], need to broadcast to [16,16]
    %1 = stablehlo.broadcast_in_dim %bias, dims = [1]
      : (tensor<16xf32>) -> tensor<16x16xf32>
    %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

    // AvgPool1d with kernel_size=16, stride=16, no padding.
    // In PyTorch: x.unsqueeze(1) -> [16,1,16], avg_pool1d(kernel=16) -> [16,1,1], squeeze(1) -> [16,1]
    // In StableHLO: use reduce_window with window=[1,1,16], stride=[1,1,16]
    // So first, reshape [16,16] -> [16,1,16]
