    // AvgPool1d with kernel_size=16, stride=16, no padding, on axis 1
    // This is a reduce_window with window_dimensions=[1,16], window_strides=[1,16], base_dilations=[1,1], window_dilations=[1,1], padding=[[0,0],[0,0]]
    // ReduceWindow needs an init value and a computation region (sum, then divide by 16)
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %sum = stablehlo.reduce_window
      %add_bias, %zero,
      window_dimensions = dense<[1, 16]> : tensor<2xi64>,
      window_strides = dense<[1, 16]> : tensor<2xi64>,
      base_dilations = dense<[1, 1]> : tensor<2xi64>,
      window_dilations = dense<[1, 1]> : tensor<2xi64>,
