    %divisor_bcast = stablehlo.broadcast_in_dim %divisor, broadcast_dimensions = [] : (tensor<f32>) -> tensor<16x1xf32>
    %avg = stablehlo.divide %sum, %divisor_bcast : (tensor<16x1xf32>, tensor<16x1xf32>) -> tensor<16x1xf32>
    // Squeeze axis 1: (16,1) -> (16)
    %avg_squeezed = stablehlo.reshape %avg : (tensor<16x1xf32>) -> tensor<16xf32>
    // GELU: x * 0.5 * (1 + erf(x / sqrt(2)))
    %half = stablehlo.constant dense<0.5> : tensor<f32>
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>
    // x / sqrt(2)
    %sqrt2_bcast = stablehlo.broadcast_in_dim %sqrt2, broadcast_dimensions = [] : (tensor<f32>) -> tensor<16xf32>
    %x_div_sqrt2 = stablehlo.divide %avg_squeezed, %sqrt2_bcast : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>
    // erf(x / sqrt(2))
    %erf = chlo.erf %x_div_sqrt2 : (tensor<16xf32>) -> tensor<16xf32>
    // 1 + erf(...)
    %one_bcast = stablehlo.broadcast_in_dim %one, broadcast_dimensions = [] : (tensor<f32>) -> tensor<16xf32>
    %erf_plus_one = stablehlo.add %one_bcast, %erf : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>
    // 0.5 * (1 + erf(...))
    %half_bcast = stablehlo.broadcast_in_dim %half, broadcast_dimensions = [] : (tensor<f32>) -> tensor<16xf32>
    %gelu_inner = stablehlo.multiply %half_bcast, %erf_plus_one : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>
    // x * ...
    %gelu = stablehlo.multiply %avg_squeezed, %gelu_inner : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>
    // Scale: * 2.0
    %scale = stablehlo.constant dense<2.0> : tensor<f32>
    %scale_bcast = stablehlo.broadcast_in_dim %scale, broadcast_dimensions = [] : (tensor<f32>) -> tensor<16xf32>
    %scaled = stablehlo.multiply %gelu, %scale_bcast : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>
    // Max over axis 1 (which is now the only axis): output is scalar per batch, but our batch is axis 0, so reduce over axis 1 of (16xf32) -> (f32) per batch
