    %scaled_2d = stablehlo.reshape %scaled : (tensor<16xf32>) -> tensor<16x1xf32>
    %minf = stablehlo.constant dense<-3.40282347E+38> : tensor<f32>
    %max = stablehlo.reduce
      %scaled_2d, %minf,
      dimensions = dense<[1]> : tensor<1xi64>
      {
        ^bb0(%a: tensor<f32>, %b: tensor<f32>):
          %r = stablehlo.maximum %a, %b : (tensor<f32>, tensor<f32>) -> tensor<f32>
          stablehlo.return %r : tensor<f32>
      }
      : (tensor<16x1xf32>, tensor<f32>) -> tensor<16xf32>
    // Return
    return %max : tensor<16xf32>
  }
}
