    // kernel: [in_c, out_c, kd, kh, kw] = [6, 7, 5, 5, 5]
    // For StableHLO: lhs = input, rhs = kernel, but for transposed conv, swap roles and set feature_group_count = in_c

    // For transposed conv, we use:
    //   lhs: [N, in_c, D, H, W] (input)
    //   rhs: [in_c, out_c, kd, kh, kw] (weight)
    //   window_strides = [2,2,2]
    //   padding = [2,2,2] on both sides
    //   lhs_dilation = [1,1,1]
    //   rhs_dilation = [1,1,1]
    //   feature_group_count = 1

    // But for transposed conv, we swap lhs/rhs and set rhs_dilation = stride, padding = kernel_size - 1 - padding
    // See: https://github.com/openxla/stablehlo/issues/1102

    // So:
    //   lhs: [N, in_c, D, H, W] = [16, 6, 6, 6, 6]
    //   rhs: [in_c, out_c, kd, kh, kw] = [6, 7, 5, 5, 5]
    //   window_strides = [1,1,1]
    //   padding = [4,4], [4,4], [4,4]  (kernel_size-1-padding = 5-1-2=2, so pad = 2)
    //   rhs_dilation = [2,2,2] (stride)
    //   lhs_dilation = [1,1,1]
    //   feature_group_count = 1

