module {
  func.func @main(
    %arg0: tensor<6x1x1xf32>,      // bias (for add after softmax)
    %arg1: tensor<7x6x4x4xf32>,    // conv_transpose.weight (IC, OC, KH, KW)
    %arg2: tensor<6xf32>,          // conv_transpose.bias
    %arg3: tensor<6x7x7x7xf32>     // input (N, IC, H, W)
  ) -> tensor<6x6x15x15xf32> {
    // 1. ConvTranspose2d (input: N, IC, H, W; weight: IC, OC, KH, KW)
    // PyTorch: out = conv_transpose(x, weight, bias, stride=2, padding=1, output_padding=1)
    // StableHLO: use convolution with swapped lhs/rhs and appropriate dimension_numbers

    // Transpose weight from (IC, OC, KH, KW) to (OC, IC, KH, KW)
    %w = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x6x4x4xf32>) -> tensor<6x7x4x4xf32>

    // ConvTranspose2d is implemented as a convolution with:
    // - input: (N, IC, H, W)
    // - kernel: (OC, IC, KH, KW)
    // - output: (N, OC, OH, OW)
    // - window_strides = (1, 1)
    // - lhs_dilation = (2, 2) (stride)
    // - rhs_dilation = (1, 1)
    // - padding = (3, 3) (see below)
    // - output_padding = (1, 1) (handled by padding)
    // PyTorch's ConvTranspose2d with stride=2, padding=1, output_padding=1, kernel_size=4
    // The equivalent convolution parameters:
    //   - window_strides = (1, 1)
    //   - padding = (3, 3) (see PyTorch docs for formula)
    //   - lhs_dilation = (2, 2)
    //   - rhs_dilation = (1, 1)
    //   - dimension_numbers = [N, C, H, W] x [O, I, KH, KW] -> [N, O, H, W]
    //   - feature_group_count = 1

    // Calculate padding for transposed convolution:
    //   padding = kernel_size - padding - 1
    //   For both sides: (kernel_size - padding - 1, kernel_size - padding - 1)
    //   kernel_size = 4, padding = 1
    //   so: 4 - 1 - 1 = 2
    //   But output_padding=1, so add 1 to the right side
    //   So: (2, 2+1) = (2, 3)
    // But StableHLO expects [[pad_top, pad_bottom], [pad_left, pad_right]]
    // PyTorch applies output_padding to the right/bottom side.
    // So: [[2, 3], [2, 3]]

    %conv = "stablehlo.convolution"(%arg3, %w) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[2, 3], [2, 3]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 2, 2>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x15x15xf32>

    // Add conv_transpose.bias (shape [6]) to output (N, OC, OH, OW)
    // Need to broadcast bias to (N, OC, OH, OW)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x15x15xf32>
    %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x15x15xf32>

    // 2. Softmax along channel dim (dim=1, OC)
    // Softmax(x) = exp(x - max(x, dim)) / sum(exp(x - max(x, dim)), dim)
    // Compute max along dim=1 (OC)
    %neg_inf = stablehlo.constant dense<-3.4028235e+38> : tensor<f32>
    %neg_inf_bcast = "stablehlo.broadcast_in_dim"(%neg_inf) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
    %max = "stablehlo.reduce"(%conv_bias, %neg_inf) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %m = stablehlo.maximum %a, %b : tensor<f32>
        "stablehlo.return"(%m) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x15x15xf32>
    // Broadcast max to (6,6,15,15) for subtraction
    %max_bcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<6x15x15xf32>) -> tensor<6x6x15x15xf32>
    %centered = stablehlo.subtract %conv_bias, %max_bcast : tensor<6x6x15x15xf32>
    %exp = stablehlo.exponential %centered : tensor<6x6x15x15xf32>
    // Sum exp along dim=1 (OC)
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %sum = "stablehlo.reduce"(%exp, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
