module {
  func.func @main(
      %bias: tensor<6x1x1xf32>, 
      %weight: tensor<7x6x4x4xf32>, 
      %conv_bias: tensor<6xf32>, 
      %input: tensor<6x7x7x7xf32>
    ) -> tensor<6x6x15x15xf32> 
  {
    // 1. ConvTranspose2d (NCHW): 
    //   input: [6,7,7,7]
    //   weight: [7,6,4,4] (IC,OC,KH,KW)
    //   bias: [6]
    //   stride: (2,2)
    //   padding: (1,1)
    //   output_padding: (1,1)
    //   output shape: [6,6,15,15]

    // StableHLO convolution is not transposed, so we use reverse and padding to simulate ConvTranspose2d.
    // See: https://pytorch.org/docs/stable/generated/torch.nn.ConvTranspose2d.html

    // Reverse spatial dims of weight (KH,KW)
    %weight_rev = stablehlo.reverse %weight, dims = [2, 3] : tensor<7x6x4x4xf32> to tensor<7x6x4x4xf32>

    // Swap IC/OC for transposed convolution: [IC,OC,KH,KW] -> [OC,IC,KH,KW]
    %weight_t = stablehlo.transpose %weight_rev, [1,0,2,3] : tensor<7x6x4x4xf32> to tensor<6x7x4x4xf32>

    // Calculate padding for transposed convolution:
    // For ConvTranspose2d, output shape:
    //   (N, C_out, H_out, W_out) where
    //   H_out = (H_in - 1) * stride[0] - 2*padding[0] + kernel_size[0] + output_padding[0]
    //   W_out = (W_in - 1) * stride[1] - 2*padding[1] + kernel_size[1] + output_padding[1]
    // Here: H_in=7, stride=2, padding=1, kernel=4, output_padding=1
    //   H_out = (7-1)*2 - 2*1 + 4 + 1 = 6*2 - 2 + 4 + 1 = 12 - 2 + 4 + 1 = 15
    //   W_out = 15

    // For transposed convolution in StableHLO, we use convolution with stride=1 and appropriate padding and dilation.
    // To simulate ConvTranspose2d with stride=2, we upsample input by inserting zeros between elements (dilate input).
    // So, we use input_dilation = (2,2), window_strides = (1,1), padding = (3,3) on both sides.

    // Input: [N,C,H,W] = [6,7,7,7]
    // Weight: [OC,IC,KH,KW] = [6,7,4,4]
    // Output: [N,OC,OH,OW] = [6,6,15,15]

    // Set up convolution parameters
    // input_dilation = (2,2)
    // window_strides = (1,1)
    // padding = (3,3) on both sides

    // Convolution
    %conv = stablehlo.convolution(
      %input, %weight_t,
      window_strides = [1, 1],
      padding = [3, 3, 3, 3],
      lhs_dilation = [2, 2],
      rhs_dilation = [1, 1],
      dimension_numbers = [
        // input: NCHW = 0,1,2,3
        // kernel: OIHW = 0,1,2,3
        // output: NCHW = 0,1,2,3
        [0, 1, 2, 3], // input dims: N,C,H,W
        [0, 1, 2, 3], // kernel dims: O,I,H,W
        [0, 1, 2, 3]  // output dims: N,C,H,W
      ],
      feature_group_count = 1,
      batch_group_count = 1,
      precision_config = []
    ) : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x15x15xf32>

    // Add conv_bias: [6] -> [1,6,1,1], then broadcast to [6,6,15,15]
    %conv_bias_reshape = stablehlo.reshape %conv_bias : tensor<6xf32> to tensor<1x6x1x1xf32>
    %conv_bias_bcast = stablehlo.broadcast_in_dim %conv_bias_reshape, dims = [1] : tensor<1x6x1x1xf32> to tensor<6x6x15x15xf32>
    %conv_bias_add = stablehlo.add %conv, %conv_bias_bcast : tensor<6x6x15x15xf32>

    // Softmax along channel dim (dim=1)
    // For softmax, subtract max for numerical stability, then exp, then sum, then divide.
    // 1. max along dim=1
    %softmax_max = stablehlo.reduce %conv_bias_add, %neg_inf
      reducer = @max_f32
      dimensions = [1]
    : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x1x15x15xf32>
    // Broadcast max to [6,6,15,15]
    %softmax_max_bcast = stablehlo.broadcast_in_dim %softmax_max, dims = [0,2,3] : tensor<6x1x15x15xf32> to tensor<6x6x15x15xf32>
    // Subtract max
    %softmax_shifted = stablehlo.subtract %conv_bias_add, %softmax_max_bcast : tensor<6x6x15x15xf32>
    // Exp
    %softmax_exp = stablehlo.exponential %softmax_shifted : tensor<6x6x15x15xf32>
    // Sum along dim=1
    %softmax_sum = stablehlo.reduce %softmax_exp, %zero
      reducer = @add_f32
      dimensions = [1]
    : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x1x15x15xf32>
    // Broadcast sum to [6,6,15,15]
    %softmax_sum_bcast = stablehlo.broadcast_in_dim %softmax_sum, dims = [0,2,3] : tensor<6x1x15x15xf32> to tensor<6x6x15x15xf32>
    // Divide
    %softmax = stablehlo.divide %softmax_exp, %softmax_sum_bcast : tensor<6x6x15x15xf32>

    // Add bias: %bias [6x1x1] -> [1,6,1,1], then broadcast to [6,6,15,15]
    %bias_reshape = stablehlo.reshape %bias : tensor<6x1x1xf32> to tensor<1x6x1x1xf32>
    %bias_bcast = stablehlo.broadcast_in_dim %bias_reshape, dims = [1] : tensor<1x6x1x1xf32> to tensor<6x6x15x15xf32>
    %add_bias = stablehlo.add %softmax, %bias_bcast : tensor<6x6x15x15xf32>

    // Multiply by scaling factor 2.0
    %scale = stablehlo.constant dense<2.0> : tensor<f32>
    %scale_bcast = stablehlo.broadcast_in_dim %scale, dims = [] : tensor<f32> to tensor<6x6x15x15xf32>
    %scaled = stablehlo.multiply %add_bias, %scale_bcast : tensor<6x6x15x15xf32>

    // Sigmoid: 1 / (1 + exp(-x))
    %neg = stablehlo.negate %scaled : tensor<6x6x15x15xf32>
    %exp_neg = stablehlo.exponential %neg : tensor<6x6x15x15xf32>
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %one_bcast = stablehlo.broadcast_in_dim %one, dims = [] : tensor<f32> to tensor<6x6x15x15xf32>
    %denom = stablehlo.add %one_bcast, %exp_neg : tensor<6x6x15x15xf32>
    %sigmoid = stablehlo.divide %one_bcast, %denom : tensor<6x6x15x15xf32>

    return %sigmoid : tensor<6x6x15x15xf32>

