module {
  func.func @main(
    %arg0: tensor<6x1x1xf32>,      // bias: (6,1,1)
    %arg1: tensor<7x6x4x4xf32>,    // conv_transpose.weight: (in=7, out=6, kh=4, kw=4)
    %arg2: tensor<6xf32>,          // conv_transpose.bias: (6)
    %arg3: tensor<6x7x7x7xf32>     // input: (N=6, C=7, H=7, W=7)
  ) -> tensor<6x6x15x15xf32> {
    // 1. Transposed convolution (ConvTranspose2d)
    // PyTorch weight: (in=7, out=6, kh=4, kw=4)
    // StableHLO expects kernel: (out, in, kh, kw)
    // But PyTorch ConvTranspose2d expects (in, out, kh, kw), so we need to swap axes 0 and 1.
    %w = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x6x4x4xf32>) -> tensor<6x7x4x4xf32>

    // For transposed convolution, use lhs_dilation = stride, rhs_dilation = 1, and spatially reverse the kernel.
    // stride = 2, padding = 1, output_padding = 1, kernel_size = 4
    // Output shape: (N, out_channels, H_out, W_out)
    // H_out = (H_in - 1) * stride - 2*padding + kernel_size + output_padding
    //       = (7-1)*2 - 2*1 + 4 + 1 = 6*2 - 2 + 4 + 1 = 12 - 2 + 4 + 1 = 15
    // So output: (6, 6, 15, 15)

    // Reverse kernel spatial dims (2,3)
    %w_rev = "stablehlo.reverse"(%w) {dimensions = array<i64: 2, 3>} : (tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    // Convolution parameters:
    // window_strides = (1, 1)
    // padding = ((kernel_size-1 - padding, kernel_size-1 - padding)) = (2,2)
    // lhs_dilation = (2,2) (stride)
    // rhs_dilation = (1,1)
    // dimension_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1] (NCHW)
    // feature_group_count = 1

    // Calculate padding for transposed convolution:
    // For PyTorch ConvTranspose2d, the equivalent StableHLO padding is:
    //   padding = (kernel_size - 1 - padding, kernel_size - 1 - padding)
    //   = (4-1-1, 4-1-1) = (2,2)
    %padding = "stablehlo.constant"() {value = dense<[[2, 2], [2, 2]]> : tensor<2x2xi64>} : () -> tensor<2x2xi64>

    // Convolution
