  %scale_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %gemm_bias, %scale_bcast : tensor<6x7xf32>
  // BatchNorm1d (training): y = (x - mean) / sqrt(var + eps) * weight + bias
  // Compute mean over batch (dim 0): shape [7]
  %c0 = stablehlo.constant dense<0> : tensor<i64>
