func.func @main(
    %arg0: tensor<16xf32>,      // multiply_weight
    %arg1: tensor<16x16xf32>,   // gemm.weight
    %arg2: tensor<16xf32>,      // gemm.bias
    %arg3: tensor<16xf32>,      // group_norm.weight
    %arg4: tensor<16xf32>,      // group_norm.bias
    %arg5: tensor<16x16xf32>    // input x
) -> tensor<16x16xf32> {
  // GEMM: x @ W^T + b
  // %arg5: [16,16], %arg1: [16,16] (PyTorch Linear: out_features x in_features)
  // Need to transpose weight to [16,16] -> [16,16] (but it's square, so no-op)
  // But for generality, transpose last two dims
  %wT = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // Dot: [16,16] x [16,16] -> [16,16]
  %gemm = "stablehlo.dot_general"(%arg5, %wT) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]
    >
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Add bias: [16] -> [16,16] (broadcast bias over batch)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x1 = stablehlo.add %gemm, %bias_bcast : tensor<16x16xf32>

  // GroupNorm: num_groups=16, num_channels=16, so each group is 1 channel
  // GroupNorm(x) = (x - mean) / sqrt(var + eps) * weight + bias
  // mean/var over (N, C//G) for each group, here C//G=1, so mean/var over dim 0 for each channel
  // Compute mean: reduce over dim 0, keep dim 1 (channels)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x1, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
  // mean = sum / N
  %n_const = stablehlo.constant dense<16.0> : tensor<f32>
  %mean = stablehlo.divide %mean, %n_const : tensor<16xf32>
  // Broadcast mean to [16,16]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  // x - mean
  %x_centered = stablehlo.subtract %x1, %mean_bcast : tensor<16x16xf32>
  // (x - mean)^2
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<16x16xf32>
  // var = mean of squared diffs: sum over dim 0, then /N
  %var = "stablehlo.reduce"(%x_centered_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
