  func.func @main(
      %multiply_weight: tensor<16xf32>,    // arg0: groupnorm/multiply weight (shape [16])
      %gemm_weight: tensor<16x16xf32>,     // arg1: gemm.weight (shape [16,16])
      %gemm_bias: tensor<16xf32>,          // arg2: gemm.bias (shape [16])
      %groupnorm_weight: tensor<16xf32>,   // arg3: groupnorm.weight (shape [16])
      %groupnorm_bias: tensor<16xf32>,     // arg4: groupnorm.bias (shape [16])
      %x: tensor<16x16xf32>                // arg5: input (shape [16,16])
    ) -> tensor<16x16xf32> {

    // GEMM: y = x @ W^T + b
    // dot_general: lhs [16,16], rhs [16,16], contracting dim 1 of lhs with dim 1 of rhs (so rhs must be transposed)
    %gemm = "stablehlo.dot_general"(%x, %gemm_weight) {
      lhs_contracting_dimensions = dense<[1]> : tensor<1xi64>,
      rhs_contracting_dimensions = dense<[1]> : tensor<1xi64>,
      lhs_batching_dimensions = dense<[0]> : tensor<1xi64>,
      rhs_batching_dimensions = dense<[]> : tensor<0xi64>
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Add bias: broadcast bias [16] to [16,16]
    %gemm_bias_bcast = "stablehlo.broadcast_in_dim"(%gemm_bias) {
      broadcast_dimensions = dense<[1]> : tensor<1xi64>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    %y0 = "stablehlo.add"(%gemm, %gemm_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // GroupNorm: num_groups=16, so each channel is its own group (InstanceNorm)
    // Compute mean over axis 1 (channels)
    %mean = "stablehlo.reduce"(%y0, %cst_zero) ({
      ^bb0(%a: f32, %b: f32):
        %sum = "stablehlo.add"(%a, %b) : (f32, f32) -> f32
        "stablehlo.return"(%sum) : (f32) -> ()
    }) { dimensions = dense<[1]> : tensor<1xi64> } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
    // Broadcast mean to [16,16]
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<16xf32>) -> tensor<16x16xf32>

    // Subtract mean
    %centered = "stablehlo.subtract"(%y0, %mean_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Square
    %centered_sq = "stablehlo.multiply"(%centered, %centered) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
