module {
  func.func @main(
    %arg0: tensor<16xf32>,      // multiply_weight
    %arg1: tensor<16x16xf32>,   // gemm.weight
    %arg2: tensor<16xf32>,      // gemm.bias
    %arg3: tensor<16xf32>,      // group_norm.weight
    %arg4: tensor<16xf32>,      // group_norm.bias
    %arg5: tensor<16x16xf32>    // input x
  ) -> tensor<16x16xf32> {
    // GEMM: x @ W^T + b
    // PyTorch Linear: y = x @ W^T + b
    // %arg5: (16,16), %arg1: (16,16) (weight), want x @ W^T
    %wT = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %gemm = "stablehlo.dot_general"(
      %arg5, %wT
    ) {
      lhs_batching_dimensions = dense<[]> : tensor<0xi64>,
      rhs_batching_dimensions = dense<[]> : tensor<0xi64>,
      lhs_contracting_dimensions = dense<[1]> : tensor<1xi64>,
      rhs_contracting_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Add bias: %arg2 shape (16,) -> broadcast to (16,16)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %gemm_bias = "stablehlo.add"(%gemm, %bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // GroupNorm: num_groups=16, out_features=16, so each group is 1 channel
    // GroupNorm(x): for each sample n and channel c: y[n,c] = (x[n,c] - mean[n,c]) / sqrt(var[n,c] + eps) * weight[c] + bias[c]
    // mean/var over axis=1 (channel), but since group=16, each group is 1 channel, so mean/var over axis=1 for each (n,c) is just x[n,c] itself
    // But PyTorch GroupNorm with num_groups==num_channels is LayerNorm over axis=1 for each row.
    // So mean/var over axis=1 for each row.

    // Compute mean over axis=1 (channels)
    %c16 = "stablehlo.constant"() {value = dense<16> : tensor<i32>} : () -> tensor<i32>
    %f16 = "stablehlo.constant"() {value = dense<16.0> : tensor<f32>} : () -> tensor<f32>
    %reduce_mean_init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %mean = "stablehlo.reduce"(%gemm_bias, %reduce_mean_init) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%add) : (tensor<f32>) -> ()
    }) {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
    // mean shape (16,), need to divide by 16
    %mean_div = "stablehlo.divide"(%mean, %f16) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
    // Broadcast mean to (16,16)
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
    // x - mean
    %centered = "stablehlo.subtract"(%gemm_bias, %mean_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // (x - mean)^2
    %centered2 = "stablehlo.multiply"(%centered, %centered) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // variance: mean of squared centered, over axis=1
    %reduce_var_init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %var = "stablehlo.reduce"(%centered2, %reduce_var_init) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%add) : (tensor<f32>) -> ()
    }) {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
    %var_div = "stablehlo.divide"(%var, %f16) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
    // Broadcast var to (16,16)
    %var_bcast = "stablehlo.broadcast_in_dim"(%var_div) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
    // Add epsilon for numerical stability
    %eps = "stablehlo.constant"() {value = dense<1.0E-5> : tensor<f32>} : () -> tensor<f32>
    %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
    %var_eps = "stablehlo.add"(%var_bcast, %eps_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %std = "stablehlo.sqrt"(%var_eps) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // Normalize: (x - mean) / sqrt(var + eps)
    %normed = "stablehlo.divide"(%centered, %std) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Scale and shift: normed * weight + bias
    // weight, bias: (16,) -> broadcast to (16,16) along axis=1
    %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %normed_scaled = "stablehlo.multiply"(%normed, %gn_weight_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %gn_out = "stablehlo.add"(%normed_scaled, %gn_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Swish: x * sigmoid(x)
    // sigmoid(x) = 1 / (1 + exp(-x))
