    // x: (16,16), gemm_weight: (16,16) (PyTorch: out_features x in_features)
    // dot_general: lhs_contracting=[1], rhs_contracting=[1]
    %0 = "stablehlo.dot_general"(%x, %gemm_weight) {
      dot_dimension_numbers = #stablehlo.dot<
        lhs_contracting_dimensions = [1], 
        rhs_contracting_dimensions = [1]
      >
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Add bias: gemm_bias shape (16,) -> (1,16) -> (16,16)
    %1 = "stablehlo.broadcast_in_dim"(%gemm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

    // GroupNorm: num_groups=16, num_channels=16, so each group is 1 channel
    // Per group: mean/var over (N, C=1) for each channel
    // So, mean/var over axis=0 for each channel (axis 0: batch, axis 1: channel)
    // Compute mean over batch (axis=0), keepdims for broadcasting
    %c0 = stablehlo.constant dense<0.0> : tensor<f32>
    %3 = "stablehlo.reduce"(%2, %c0) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
    // mean = sum / N
    %c16 = stablehlo.constant dense<16.0> : tensor<f32>
    %4 = "stablehlo.broadcast_in_dim"(%c16) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16xf32>
    %5 = stablehlo.divide %3, %4 : tensor<16xf32>
    // Broadcast mean to (16,16)
    %6 = "stablehlo.broadcast_in_dim"(%5) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    // x - mean
    %7 = stablehlo.subtract %2, %6 : tensor<16x16xf32>
    // (x - mean)^2
    %8 = stablehlo.multiply %7, %7 : tensor<16x16xf32>
    // var = mean((x - mean)^2) over axis=0
    %9 = "stablehlo.reduce"(%8, %c0) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
