    %10 = stablehlo.divide %9, %4 : tensor<16xf32>
    // Broadcast var to (16,16)
    %11 = "stablehlo.broadcast_in_dim"(%10) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
