    // (x - mean) / sqrt(var + eps)
    %15 = stablehlo.divide %7, %14 : tensor<16x16xf32>
    // Apply scale (group_norm.weight) and bias (group_norm.bias): shape (16,) -> (1,16) -> (16,16)
