    %23 = stablehlo.add %22, %21 : tensor<16x16xf32>
    %24 = stablehlo.divide %22, %23 : tensor<16x16xf32>
    %25 = stablehlo.multiply %19, %24 : tensor<16x16xf32>

    // Multiply by multiply_weight: shape (16,) -> (1,16) -> (16,16)
    %26 = "stablehlo.broadcast_in_dim"(%multiply_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %27 = stablehlo.multiply %25, %26 : tensor<16x16xf32>

    // Swish again: x * sigmoid(x)
    %28 = stablehlo.negate %27 : tensor<16x16xf32>
    %29 = stablehlo.exponential %28 : tensor<16x16xf32>
    %30 = stablehlo.add %22, %29 : tensor<16x16xf32>
    %31 = stablehlo.divide %22, %30 : tensor<16x16xf32>
    %32 = stablehlo.multiply %27, %31 : tensor<16x16xf32>

