  // Entry function
  func.func @main(
      %multiply_weight: tensor<16xf32>,      // arg0: multiply_weight
      %gemm_weight: tensor<16x16xf32>,       // arg1: gemm.weight (out_features x in_features)
      %gemm_bias: tensor<16xf32>,            // arg2: gemm.bias (out_features)
      %group_norm_weight: tensor<16xf32>,    // arg3: group_norm.weight (out_features)
      %group_norm_bias: tensor<16xf32>,      // arg4: group_norm.bias (out_features)
      %input: tensor<16x16xf32>              // arg5: input (batch_size x in_features)
    ) -> tensor<16x16xf32> {
