    // GEMM: y = x @ W^T + b
    // x: [16,16], W: [16,16] (out_features x in_features), b: [16]
    // PyTorch Linear uses x @ W^T, so we need to transpose W

    // Transpose gemm_weight from [16,16] to [16,16] (no-op, but for clarity)
    %gemm_weight_t = stablehlo.transpose %gemm_weight, [1, 0] : (tensor<16x16xf32>) -> tensor<16x16xf32>

    // DotGeneral: lhs [16,16], rhs [16,16], contracting on dim 1 of lhs and dim 0 of rhs
    %gemm_out = stablehlo.dot_general
      %input, %gemm_weight_t,
      {
        lhs_contracting_dimensions = dense<[1]> : tensor<1xi64>,
        rhs_contracting_dimensions = dense<[0]> : tensor<1xi64>,
        lhs_batch_dimensions = dense<[]> : tensor<0xi64>,
        rhs_batch_dimensions = dense<[]> : tensor<0xi64>
      }
      : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Add bias: [16x16] + [16] (broadcast bias over dim 0)
    %gemm_bias_bcast = stablehlo.broadcast_in_dim %gemm_bias, dims = [1] : (tensor<16xf32>) -> tensor<16x16xf32>
    %post_gemm = stablehlo.add %gemm_out, %gemm_bias_bcast : tensor<16x16xf32>

    // GroupNorm: num_groups=16, num_channels=16, so each group has 1 channel
    // Reshape to [batch, num_groups, group_size] = [16,16,1]
    %reshaped = stablehlo.reshape %post_gemm : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

    // Compute mean over group_size axis (axis=2)
    %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
    %mean = stablehlo.reduce
      %reshaped, %cst_zero
      (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16x1xf32>
      {
        dimensions = [2],
        body = @mean_add
      }

    // mean = sum / group_size (group_size=1)
    %group_size_cst = stablehlo.constant dense<1.0> : tensor<f32>
