      %centered_sq, %cst_zero
      (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16x1xf32>
      {
        dimensions = [2],
        body = @mean_add
      }
    %var = stablehlo.divide %var, %group_size_cst : tensor<16x16x1xf32>, tensor<f32> -> tensor<16x16x1xf32>

