    %affine = stablehlo.add %affine, %bias_bcast : tensor<16x16xf32>

    // Swish: x * sigmoid(x)
    // sigmoid(x) = 1 / (1 + exp(-x))
    %neg_affine = stablehlo.negate %affine : tensor<16x16xf32>
    %exp_neg_affine = stablehlo.exponential %neg_affine : tensor<16x16xf32>
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %one_bcast = stablehlo.broadcast_in_dim %one, dims = [] : (tensor<f32>) -> tensor<16x16xf32>
    %denom = stablehlo.add %one_bcast, %exp_neg_affine : tensor<16x16xf32>
    %sigmoid = stablehlo.divide %one_bcast, %denom : tensor<16x16xf32>
    %swish1 = stablehlo.multiply %affine, %sigmoid : tensor<16x16xf32>

    // Multiply by multiply_weight: [16x16] * [16] (broadcast over batch)
    %multiply_weight_bcast = stablehlo.broadcast_in_dim %multiply_weight, dims = [1] : (tensor<16xf32>) -> tensor<16x16xf32>
    %mul = stablehlo.multiply %swish1, %multiply_weight_bcast : tensor<16x16xf32>

    // Swish again: x * sigmoid(x)
    %neg_mul = stablehlo.negate %mul : tensor<16x16xf32>
    %exp_neg_mul = stablehlo.exponential %neg_mul : tensor<16x16xf32>
    %denom2 = stablehlo.add %one_bcast, %exp_neg_mul : tensor<16x16xf32>
    %sigmoid2 = stablehlo.divide %one_bcast, %denom2 : tensor<16x16xf32>
    %swish2 = stablehlo.multiply %mul, %sigmoid2 : tensor<16x16xf32>

    return %swish2 : tensor<16x16xf32>
  }
