      padding = [0, 0, 0, 0],
      lhs_dilation = [1, 1],
      rhs_dilation = [1, 1],
      dimension_numbers = [
        // input: N, C, H, W
        0, 1, 2, 3,
        // kernel: O, I, kH, kW
