    %bias_broadcast = stablehlo.broadcast_in_dim %arg1, dims = [1]
      : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %biased = stablehlo.add %conv, %bias_broadcast
      : tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32> -> tensor<6x7x4x4xf32>

    // ---- HardSwish ----
    // hardswish(x) = x * relu6(x + 3) / 6
    // relu6(x) = min(max(x, 0), 6)
    %cst_3 = stablehlo.constant dense<3.0> : tensor<f32>
    %cst_6 = stablehlo.constant dense<6.0> : tensor<f32>
    %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>
    %cst_6_broadcast = stablehlo.broadcast_in_dim %cst_6, dims = []
      : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %cst_0_broadcast = stablehlo.broadcast_in_dim %cst_0, dims = []
      : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %cst_3_broadcast = stablehlo.broadcast_in_dim %cst_3, dims = []
      : (tensor<f32>) -> tensor<6x7x4x4xf32>

    %x_plus_3 = stablehlo.add %biased, %cst_3_broadcast
      : tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32> -> tensor<6x7x4x4xf32>
    %relu6_0 = stablehlo.maximum %x_plus_3, %cst_0_broadcast
