    %relu6 = stablehlo.minimum %relu6_0, %cst_6_broadcast
      : tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32> -> tensor<6x7x4x4xf32>
    %hardswish_num = stablehlo.multiply %biased, %relu6
      : tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32> -> tensor<6x7x4x4xf32>
    %hardswish = stablehlo.divide %hardswish_num, %cst_6_broadcast
      : tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32> -> tensor<6x7x4x4xf32>

