    %normed = "stablehlo.divide"(%centered, %std) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Apply scale and bias (per channel)
    %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
