    %scaled = "stablehlo.multiply"(%normed, %gn_weight_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %out = "stablehlo.add"(%scaled, %gn_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

