      %matmul_bias: tensor<16xf32>,         // arg2: matmul.bias
      %group_norm_weight: tensor<16xf32>,   // arg3: group_norm.weight
      %group_norm_bias: tensor<16xf32>,     // arg4: group_norm.bias
      %x: tensor<16x16xf32>                 // arg5: input (batch_size x in_features)
