    // ---- Linear: x @ W^T + b ----
    // x: [16,16], matmul_weight: [16,16] (out_features x in_features)
    // PyTorch Linear: y = x @ W^T + b
    // So, dot_general with lhs: x [B, I], rhs: matmul_weight [O, I], contracting on I
    // We need to transpose matmul_weight to [I, O] or use dot_general with appropriate dims.

    // dot_general: lhs [B, I], rhs [O, I], contract on I
    // So, transpose matmul_weight to [I, O]
    %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
    %cst_one = stablehlo.constant dense<1.0> : tensor<f32>
    %cst_eps = stablehlo.constant dense<1.0e-5> : tensor<f32>

    // Transpose matmul_weight [16,16] to [16,16] (swap axes 0 and 1)
    %matmul_weight_T = stablehlo.transpose(%matmul_weight, [1, 0]) : (tensor<16x16xf32>) -> tensor<16x16xf32>

    // DotGeneral: lhs [16,16], rhs [16,16], contract on dim 1 of lhs and dim 0 of rhs
    %linear = stablehlo.dot_general(
      %x, %matmul_weight_T,
      {
        // contracting dims: lhs [1], rhs [0]
        // batch dims: none
        lhs_contracting_dimensions = dense<[1]> : tensor<1xi64>,
        rhs_contracting_dimensions = dense<[0]> : tensor<1xi64>,
        lhs_batch_dimensions = dense<[]> : tensor<0xi64>,
        rhs_batch_dimensions = dense<[]> : tensor<0xi64>
      }
    ) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Add matmul_bias: [16] -> [16,16] (broadcast on axis 1)
    %matmul_bias_bcast = stablehlo.broadcast_in_dim(%matmul_bias, [16,16], [1]) : (tensor<16xf32>) -> tensor<16x16xf32>
    %linear_bias = stablehlo.add(%linear, %matmul_bias_bcast) : tensor<16x16xf32>

    // ---- Swish activation: sigmoid(x) * x ----
    // sigmoid(x) = 1 / (1 + exp(-x))
    %neg_linear = stablehlo.negate(%linear_bias) : tensor<16x16xf32>
    %exp_neg_linear = stablehlo.exponential(%neg_linear) : tensor<16x16xf32>
    %exp_neg_linear_plus1 = stablehlo.add(%exp_neg_linear, %cst_one) : tensor<16x16xf32>
    %sigmoid = stablehlo.divide(%cst_one, %exp_neg_linear_plus1) : tensor<16x16xf32>
    %swish = stablehlo.multiply(%sigmoid, %linear_bias) : tensor<16x16xf32>

    // ---- Add bias parameter ----
    // bias: [16] -> [16,16] (broadcast on axis 1)
    %bias_bcast = stablehlo.broadcast_in_dim(%bias, [16,16], [1]) : (tensor<16xf32>) -> tensor<16x16xf32>
    %swish_bias = stablehlo.add(%swish, %bias_bcast) : tensor<16x16xf32>

    // ---- GroupNorm (num_groups=16, num_channels=16, affine=True, eps=1e-5) ----
    // GroupNorm with 16 groups, 16 channels: each channel is its own group.
    // So, for each (N, C), normalize over spatial dims (none here), so mean/var over axis 1 (channels).
    // For each batch element, mean/var over axis 1.

    // Compute mean over axis 1 (channels), keepdims
    %mean = stablehlo.reduce(
      %swish_bias, %cst_zero,
      stablehlo.add
    ) { dimensions = [1] } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
    // mean shape: [16]
    %mean_bcast = stablehlo.broadcast_in_dim(%mean, [16,16], [0]) : (tensor<16xf32>) -> tensor<16x16xf32>

    // Centered: x - mean
    %centered = stablehlo.subtract(%swish_bias, %mean_bcast) : tensor<16x16xf32>

    // Variance: mean((x - mean)^2) over axis 1
    %centered_sq = stablehlo.multiply(%centered, %centered) : tensor<16x16xf32>
    %var = stablehlo.reduce(
      %centered_sq, %cst_zero,
      stablehlo.add
    ) { dimensions = [1] } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
    // Divide by number of elements (channels=16)
    %cst_16 = stablehlo.constant dense<16.0> : tensor<f32>
    %var_mean = stablehlo.divide(%var, %cst_16) : tensor<16xf32>
    %var_mean_bcast = stablehlo.broadcast_in_dim(%var_mean, [16,16], [0]) : (tensor<16xf32>) -> tensor<16x16xf32>

    // Add epsilon for numerical stability
    %var_eps = stablehlo.add(%var_mean_bcast, %cst_eps) : tensor<16x16xf32>
    %rsqrt_var = stablehlo.rsqrt(%var_eps) : tensor<16x16xf32>

    // Normalize
    %normalized = stablehlo.multiply(%centered, %rsqrt_var) : tensor<16x16xf32>

    // Affine: y = normalized * weight + bias
    // group_norm_weight, group_norm_bias: [16] -> [16,16] (broadcast on axis 1)
    %gn_weight_bcast = stablehlo.broadcast_in_dim(%group_norm_weight, [16,16], [1]) : (tensor<16xf32>) -> tensor<16x16xf32>
    %gn_bias_bcast = stablehlo.broadcast_in_dim(%group_norm_bias, [16,16], [1]) : (tensor<16xf32>) -> tensor<16x16xf32>
    %affine = stablehlo.multiply(%normalized, %gn_weight_bcast) : tensor<16x16xf32>
    %out = stablehlo.add(%affine, %gn_bias_bcast) : tensor<16x16xf32>

    // Return
    func.return %out : tensor<16x16xf32>
  }
}
