func.func @main(
    %bias: tensor<16xf32>, 
    %matmul_weight: tensor<16x16xf32>, 
    %matmul_bias: tensor<16xf32>, 
    %gn_weight: tensor<16xf32>, 
    %gn_bias: tensor<16xf32>, 
    %x: tensor<16x16xf32>
) -> tensor<16x16xf32> {
  // ---- Linear: y = x @ W^T + b ----
  // matmul: (16x16) @ (16x16)^T = (16x16) @ (16x16) = (16x16)
  // But PyTorch nn.Linear uses weight of shape (out_features, in_features), so we need to transpose weight.
  %weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // dot_general: batch dims = none, contract last dim of x (1) with last dim of weight_t (1)
  %linear = "stablehlo.dot_general"(%x, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]
    >
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Add matmul bias (shape 16) to each row
  %matmul_bias_bcast = "stablehlo.broadcast_in_dim"(%matmul_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %linear_bias = stablehlo.add %linear, %matmul_bias_bcast : tensor<16x16xf32>

  // ---- Swish: sigmoid(y) * y ----
  // sigmoid(y) = 1 / (1 + exp(-y))
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %neg_linear = stablehlo.negate %linear_bias : tensor<16x16xf32>
  %exp_neg_linear = stablehlo.exponential %neg_linear : tensor<16x16xf32>
  %exp_plus_one = stablehlo.add %exp_neg_linear, %one : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one, %exp_plus_one : tensor<16x16xf32>
  %sigmoid_bcast = %sigmoid // already shape (16x16)
  %swish = stablehlo.multiply %sigmoid_bcast, %linear_bias : tensor<16x16xf32>

  // ---- Add bias ----
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_bias = stablehlo.add %swish, %bias_bcast : tensor<16x16xf32>

  // ---- GroupNorm (num_groups=16, num_channels=16, so each group is 1 channel) ----
  // GroupNorm with 16 groups and 16 channels: each channel is its own group.
  // For each channel (axis 1), normalize over batch (axis 0).
  // mean: reduce over axis 0 (batch)
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>
  %pos_inf = stablehlo.constant dense<0x7F800000> : tensor<f32>
  // Compute mean over batch (axis 0)
  %sum = "stablehlo.reduce"(%swish_bias, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
  %batch_size_c = stablehlo.constant dense<16.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %batch_size_c : tensor<16xf32>
  // Broadcast mean to (16x16)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  // Centered: x - mean
  %centered = stablehlo.subtract %swish_bias, %mean_bcast : tensor<16x16xf32>
  // Variance: mean((x - mean)^2) over batch (axis 0)
  %centered_sq = stablehlo.multiply %centered, %centered : tensor<16x16xf32>
  %var_sum = "stablehlo.reduce"(%centered_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
  %var = stablehlo.divide %var_sum, %batch_size_c : tensor<16xf32>
  // Add epsilon for numerical stability
  %eps = stablehlo.constant dense<1.0000001E-5> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<16xf32>
  %var_eps_bcast = "stablehlo.broadcast_in_dim"(%var_eps) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  // std = sqrt(var + eps)
  %std = stablehlo.sqrt %var_eps_bcast : tensor<16x16xf32>
  // normalized = (x - mean) / std
  %normalized = stablehlo.divide %centered, %std : tensor<16x16xf32>
  // Scale and shift: y = normalized * weight + bias
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %norm_scaled = stablehlo.multiply %normalized, %gn_weight_bcast : tensor<16x16xf32>
  %norm_shifted = stablehlo.add %norm_scaled, %gn_bias_bcast : tensor<16x16xf32>

  return %norm_shifted : tensor<16x16xf32>
}
