    // --- Convolution ---
    // PyTorch: input [N, C_in, H, W], weight [C_out, C_in, kH, kW], bias [C_out]
    // StableHLO: lhs [N, C_in, H, W], rhs [O, I, kH, kW]
    // Output: [N, O, H_out, W_out] = [6, 6, 4, 4]
    // Padding: kernel_size=3, stride=1, padding=0 (default for nn.Conv2d)
    // So, output H = (6 - 3)//1 + 1 = 4
    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      // Correct dimension_numbers: [b, i, 0, 1]x[o, i, 0, 1]->[b, o, 0, 1]
      //   lhs: [N, C_in, H, W] (b, i, 0, 1)
      //   rhs: [O, I, kH, kW]  (o, i, 0, 1)
      //   out: [N, O, H, W]    (b, o, 0, 1)
      dimension_numbers = #stablehlo.conv<[b, i, 0, 1]x[o, i, 0, 1]->[b, o, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

    // --- Add bias ---
    // Bias shape: [6], output shape: [6,6,4,4], need to broadcast bias along batch, H, W
    // Bias should be broadcast to [6,6,4,4] with broadcast_dimensions = [1]
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>
    %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x4x4xf32>

    // --- Subtract subtract1_value (0.5) ---
    %c_sub1 = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    // Broadcast to [6,6,4,4]
    %sub1_broadcast = "stablehlo.broadcast_in_dim"(%c_sub1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %after_sub1 = stablehlo.subtract %conv_bias, %sub1_broadcast : tensor<6x6x4x4xf32>

    // --- Tanh activation ---
    %after_tanh = stablehlo.tanh %after_sub1 : tensor<6x6x4x4xf32>

    // --- Subtract subtract2_value (0.2) ---
    %c_sub2 = "stablehlo.constant"() {value = dense<0.2> : tensor<f32>} : () -> tensor<f32>
    %sub2_broadcast = "stablehlo.broadcast_in_dim"(%c_sub2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %after_sub2 = stablehlo.subtract %after_tanh, %sub2_broadcast : tensor<6x6x4x4xf32>

    // --- AvgPool2d(kernel_size=2) ---
    // PyTorch default: stride=kernel_size, padding=0
    // Window dims: [2,2] over last two dims (H,W)
    // Output: H_out = (4-2)//2 + 1 = 2, so [6,6,2,2]
    // Reduce window with add, then divide by 4.0
    %c0_f32 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %windowed_sum = "stablehlo.reduce_window"(%after_sub2, %c0_f32) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {
      window_dimensions = array<i64: 1, 1, 2, 2>,
      window_strides = array<i64: 1, 1, 2, 2>,
      padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
    } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

    // Divide by 4.0 (kernel_size*kernel_size)
    %c4_f32 = "stablehlo.constant"() {value = dense<4.0> : tensor<f32>} : () -> tensor<f32>
    %c4_broadcast = "stablehlo.broadcast_in_dim"(%c4_f32) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x2x2xf32>
    %avgpool = stablehlo.divide %windowed_sum, %c4_broadcast : tensor<6x6x2x2xf32>

    return %avgpool : tensor<6x6x2x2xf32>
  }
}
