module {
  func.func @main(
    %arg0: tensor<7x8x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
    %arg1: tensor<7xf32>,         // conv.bias [out_c]
    %arg2: tensor<6x8x6x6xf32>    // input [N, in_c, H, W]
  ) -> tensor<6x7x4x4xf32> {
    // 1. Convolution
    // PyTorch: input[N, C_in, H, W], weight[C_out, C_in, kH, kW], bias[C_out]
    // StableHLO: input [N, C_in, H, W], kernel [C_out, C_in, kH, kW]
    // Output: [N, C_out, outH, outW]
    // Stride=1, Padding=0, Dilation=1

    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      // input: [N, C_in, H, W], kernel: [C_out, C_in, kH, kW], output: [N, C_out, outH, outW]
      dimension_numbers = #stablehlo.conv<[
        b, f, 0, 1
      ]x[
        o, i, 0, 1
      ]->[
        b, o, 0, 1
      ]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

    // 2. Add bias: bias shape [7] -> broadcast to [6,7,4,4]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

    %biased = stablehlo.add %conv, %bias_bcast : tensor<6x7x4x4xf32>

    // 3. Divide by constant divisor=2
    %cst_two = stablehlo.constant dense<2.0> : tensor<f32>
    %two_bcast = "stablehlo.broadcast_in_dim"(%cst_two) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x7x4x4xf32>

    %div = stablehlo.divide %biased, %two_bcast : tensor<6x7x4x4xf32>

    // 4. LeakyReLU: y = x if x >= 0 else 0.01 * x
    // Compute mask: x >= 0
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x7x4x4xf32>

    %ge_mask = "stablehlo.compare"(%div, %zero_bcast) {
      comparison_direction = #stablehlo<comparison_direction GE>,
      compare_type = #stablehlo<comparison_type FLOAT>
    } : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xi1>

    // Compute 0.01 * x
    %alpha = stablehlo.constant dense<0.01> : tensor<f32>
    %alpha_bcast = "stablehlo.broadcast_in_dim"(%alpha) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %leaky = stablehlo.multiply %div, %alpha_bcast : tensor<6x7x4x4xf32>

    // Select: if ge_mask then x else leaky
    %out = "stablehlo.select"(%ge_mask, %div, %leaky) : (tensor<6x7x4x4xi1>, tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    return %out : tensor<6x7x4x4xf32>
  }
