  // PyTorch: input[N, C_in, H, W], weight[C_out, C_in, kH, kW]
  // StableHLO: lhs[N, C_in, H, W], rhs[O, I, kH, kW]
  // Output: [N, O, H_out, W_out]
  // Stride=1, Padding=0, Dilation=1

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    // [N, C_in, H, W] x [O, I, kH, kW] -> [N, O, H, W]
    // StableHLO conv dimension names: [b, f, 0, 1] x [o, i, 0, 1] -> [b, f, 0, 1]
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[f, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Add bias: bias shape [7], need to broadcast to [6,7,4,4]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %biased = stablehlo.add %conv, %bias_bcast : tensor<6x7x4x4xf32>

  // Divide by constant divisor=2
  %cst_two = stablehlo.constant dense<2.0> : tensor<f32>
  %two_bcast = "stablehlo.broadcast_in_dim"(%cst_two) {
    broadcast_dimensions = array<i64: >
  } : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %div = stablehlo.divide %biased, %two_bcast : tensor<6x7x4x4xf32>

  // LeakyReLU: y = x if x >= 0 else 0.01 * x
  %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%cst_zero) {
    broadcast_dimensions = array<i64: >
  } : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %cst_neg_slope = stablehlo.constant dense<0.01> : tensor<f32>
  %neg_slope_bcast = "stablehlo.broadcast_in_dim"(%cst_neg_slope) {
    broadcast_dimensions = array<i64: >
  } : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %mul_neg = stablehlo.multiply %div, %neg_slope_bcast : tensor<6x7x4x4xf32>
  %cmp = "stablehlo.compare"(%div, %zero_bcast) {
    comparison_direction = #stablehlo<comparison_direction GE>,
    compare_type = #stablehlo<comparison_type FLOAT>
  } : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xi1>
  %leaky = "stablehlo.select"(%cmp, %div, %mul_neg) : (tensor<6x7x4x4xi1>, tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

  return %leaky : tensor<6x7x4x4xf32>
}
