  // %arg0: conv.weight [out_channels=7, in_channels=8, kh=3, kw=3]
  // %arg1: conv.bias   [out_channels=7]
  // %arg2: input       [batch=6, in_channels=8, h=6, w=6]
  // Returns:           [batch=6, out_channels=7, out_h=4, out_w=4]
  func.func @main(
    %arg0: tensor<7x8x3x3xf32>, 
    %arg1: tensor<7xf32>, 
    %arg2: tensor<6x8x6x6xf32>
  ) -> tensor<6x7x4x4xf32> {
    // Convolution: NCHW input, OIHW weight, stride=1, padding=0
    %conv = stablehlo.convolution(
      %arg2, %arg0,
      window_strides = dense<[1, 1]> : tensor<2xi64>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      feature_group_count = 1,
      batch_group_count = 1,
      dimension_numbers = #stablehlo.conv_dimension_numbers<
        input_batch_dimension = 0, input_feature_dimension = 1, input_spatial_dimensions = [2, 3],
        kernel_output_feature_dimension = 0, kernel_input_feature_dimension = 1, kernel_spatial_dimensions = [2, 3],
        output_batch_dimension = 0, output_feature_dimension = 1, output_spatial_dimensions = [2, 3]
      >
    ) : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

    // Add bias: broadcast bias [7] to [6,7,4,4] along dims [1]
    %bias_bcast = stablehlo.broadcast_in_dim %arg1, dims = [1] : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %biased = stablehlo.add %conv, %bias_bcast : tensor<6x7x4x4xf32>

    // Divide by constant divisor=2
    %cst_two = stablehlo.constant dense<2.0> : tensor<f32>
    %two_bcast = stablehlo.broadcast_in_dim %cst_two, dims = [] : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %div = stablehlo.divide %biased, %two_bcast : tensor<6x7x4x4xf32>

    // LeakyReLU: max(x, 0) + negative_slope * min(x, 0), negative_slope=0.01
    %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
    %zero_bcast = stablehlo.broadcast_in_dim %cst_zero, dims = [] : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %cst_nslope = stablehlo.constant dense<0.01> : tensor<f32>
    %nslope_bcast = stablehlo.broadcast_in_dim %cst_nslope, dims = [] : (tensor<f32>) -> tensor<6x7x4x4xf32>

    %max = stablehlo.maximum %div, %zero_bcast : tensor<6x7x4x4xf32>
    %min = stablehlo.minimum %div, %zero_bcast : tensor<6x7x4x4xf32>
    %min_scaled = stablehlo.multiply %min, %nslope_bcast : tensor<6x7x4x4xf32>
    %leaky_relu = stablehlo.add %max, %min_scaled : tensor<6x7x4x4xf32>

    return %leaky_relu : tensor<6x7x4x4xf32>
  }
