    %col1s = stablehlo.reshape %col1 : tensor<6x1xf32> -> tensor<6xf32>
    %col2s = stablehlo.reshape %col2 : tensor<6x1xf32> -> tensor<6xf32>
    %col3s = stablehlo.reshape %col3 : tensor<6x1xf32> -> tensor<6xf32>
