    %col5s = stablehlo.reshape %col5 : tensor<6x1xf32> -> tensor<6xf32>

    // Compute cumulative product along dim 1 (columns)
    // out[:, 0] = x[:, 0]
    %out0 = %col0s
    // out[:, 1] = x[:, 0] * x[:, 1]
    %out1 = stablehlo.multiply %out0, %col1s : tensor<6xf32>
    // out[:, 2] = x[:, 0] * x[:, 1] * x[:, 2]
    %out2 = stablehlo.multiply %out1, %col2s : tensor<6xf32>
