    %out3 = stablehlo.multiply %out2, %col3s : tensor<6xf32>
    // out[:, 4] = x[:, 0] * x[:, 1] * x[:, 2] * x[:, 3] * x[:, 4]
    %out4 = stablehlo.multiply %out3, %col4s : tensor<6xf32>
