    %out5 = stablehlo.multiply %out4, %col5s : tensor<6xf32>

    // Stack the outputs to shape (6,6)
    %out0r = stablehlo.reshape %out0 : tensor<6xf32> -> tensor<6x1xf32>
    %out1r = stablehlo.reshape %out1 : tensor<6xf32> -> tensor<6x1xf32>
    %out2r = stablehlo.reshape %out2 : tensor<6xf32> -> tensor<6x1xf32>
    %out3r = stablehlo.reshape %out3 : tensor<6xf32> -> tensor<6x1xf32>
    %out4r = stablehlo.reshape %out4 : tensor<6xf32> -> tensor<6x1xf32>
    %out5r = stablehlo.reshape %out5 : tensor<6xf32> -> tensor<6x1xf32>

    %result = stablehlo.concatenate %out0r, %out1r, %out2r, %out3r, %out4r, %out5r, dim = 1 : tensor<6x1xf32>, tensor<6x1xf32>, tensor<6x1xf32>, tensor<6x1xf32>, tensor<6x1xf32>, tensor<6x1xf32> -> tensor<6x6xf32>
    return %result : tensor<6x6xf32>
  }
