    // The reduction body multiplies the accumulator and the new value.
    %cumprod_rev = "stablehlo.reduce_window"(%rev, %cst) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %mul = stablehlo.multiply %a, %b : tensor<f32>
        stablehlo.return %mul : tensor<f32>
