    // PyTorch Conv2d: input [N,C,H,W], weight [O,C,kH,kW], bias [O]
    // StableHLO convolution: lhs=input, rhs=weight
    // input: [N=6, C=7, H=6, W=6]
    // weight: [O=6, C=7, kH=3, kW=3]
    // output: [N=6, O=6, H_out=4, W_out=4] (no padding, stride=1)
    // dimension_numbers: lhs=[N,C,H,W], rhs=[O,C,kH,kW], out=[N,O,H,W]
    // window_strides=[1,1], padding=[0,0,0,0], feature_group_count=1

    %conv = stablehlo.convolution(
      %input, %weight
    ) {
      window_strides = dense<[1, 1]> : tensor<2xi64>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64,
      dimension_numbers = #stablehlo.conv_dimension_numbers<
        input_batch_dimension = 0,
        input_feature_dimension = 1,
        input_spatial_dimensions = [2, 3],
        kernel_output_feature_dimension = 0,
        kernel_input_feature_dimension = 1,
        kernel_spatial_dimensions = [2, 3],
        output_batch_dimension = 0,
        output_feature_dimension = 1,
        output_spatial_dimensions = [2, 3]
      >
    } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

    // ---- Add bias ----
    // Bias shape: [6], output shape: [6,6,4,4]
    // Need to broadcast bias to [6,6,4,4] along feature dim (dim 1)
    %bias_bcast = stablehlo.broadcast_in_dim %bias, dims = [1] : (tensor<6xf32>) -> tensor<6x6x4x4xf32>
    %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x6x4x4xf32>

