    // Input: [6,6,4,4], window=[2,2], stride=[2,2], output: [6,6,2,2]
    // Reduce window over spatial dims (2,3)
    %cst_neg_inf = stablehlo.constant dense<-inf> : tensor<f32>
    %maxpool = stablehlo.reduce_window %hardswish, %cst_neg_inf
      window_dimensions = dense<[1,1,2,2]> : tensor<4xi64>,
      window_strides = dense<[1,1,2,2]> : tensor<4xi64>,
      base_dilations = dense<[1,1,1,1]> : tensor<4xi64>,
      window_dilations = dense<[1,1,1,1]> : tensor<4xi64>,
      padding = dense<[[0,0],[0,0],[0,0],[0,0]]> : tensor<4x2xi64>
    {
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %max = stablehlo.maximum %a, %b : tensor<f32>
        stablehlo.return %max : tensor<f32>
    } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

    // ---- Mish: x * tanh(softplus(x)) ----
    // softplus(x) = log(1 + exp(x))
    %exp = stablehlo.exponential %maxpool : tensor<6x6x2x2xf32>
    %cst_1 = stablehlo.constant dense<1.0> : tensor<f32>
    %exp_plus_1 = stablehlo.add %exp, (stablehlo.broadcast_in_dim %cst_1, dims = [] : (tensor<f32>) -> tensor<6x6x2x2xf32>) : tensor<6x6x2x2xf32>
    %softplus = stablehlo.log %exp_plus_1 : tensor<6x6x2x2xf32>
    %tanh = stablehlo.tanh %softplus : tensor<6x6x2x2xf32>
    %mish = stablehlo.multiply %maxpool, %tanh : tensor<6x6x2x2xf32>

    return %mish : tensor<6x6x2x2xf32>
  }
