    %cst_3 = stablehlo.constant dense<3.0> : tensor<f32>
    %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>
    %cst_6 = stablehlo.constant dense<6.0> : tensor<f32>
    %cst_6_bcast = "stablehlo.broadcast_in_dim"(%cst_6) {
      broadcast_dimensions = dense<[]> : tensor<0xi64>
    } : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %cst_3_bcast = "stablehlo.broadcast_in_dim"(%cst_3) {
      broadcast_dimensions = dense<[]> : tensor<0xi64>
    } : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %cst_0_bcast = "stablehlo.broadcast_in_dim"(%cst_0) {
