    } : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %add3 = stablehlo.add %sub, %cst_3_bcast : tensor<6x6x4x4xf32>
    %relu6_0 = stablehlo.maximum %add3, %cst_0_bcast : tensor<6x6x4x4xf32>
    %relu6 = stablehlo.minimum %relu6_0, %cst_6_bcast : tensor<6x6x4x4xf32>
    %hardswish_num = stablehlo.multiply %sub, %relu6 : tensor<6x6x4x4xf32>
    %hardswish = stablehlo.divide %hardswish_num, %cst_6_bcast : tensor<6x6x4x4xf32>

    // MaxPool2d(kernel_size=2, stride=2, padding=0)
    // Reduce window with max, window [1,1,2,2], stride [1,1,2,2], no padding
