    %init = "stablehlo.broadcast_in_dim"(%cst_neg_inf) {
      broadcast_dimensions = dense<[]> : tensor<0xi64>
    } : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %maxpool = "stablehlo.reduce_window"(%hardswish, %cst_neg_inf) ({
