    %bias_bcast = stablehlo.broadcast_in_dim %arg1, dims = [1] : (tensor<6xf32>) -> tensor<6x6x4x4xf32>
    %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x6x4x4xf32>

    // ---- Subtract constant 0.5 ----
    %cst_05 = stablehlo.constant dense<0.5> : tensor<f32>
    %cst_05_bcast = stablehlo.broadcast_in_dim %cst_05, dims = [] : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %sub = stablehlo.subtract %conv_bias, %cst_05_bcast : tensor<6x6x4x4xf32>

    // ---- HardSwish: x * relu6(x + 3) / 6 ----
    // relu6(x) = min(max(x, 0), 6)
    %cst_3 = stablehlo.constant dense<3.0> : tensor<f32>
    %cst_6 = stablehlo.constant dense<6.0> : tensor<f32>
    %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>
