    %cst_6_bcast = stablehlo.broadcast_in_dim %cst_6, dims = [] : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %cst_0_bcast = stablehlo.broadcast_in_dim %cst_0, dims = [] : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %add3 = stablehlo.add %sub, %cst_3_bcast : tensor<6x6x4x4xf32>
    %max0 = stablehlo.maximum %add3, %cst_0_bcast : tensor<6x6x4x4xf32>
    %relu6 = stablehlo.minimum %max0, %cst_6_bcast : tensor<6x6x4x4xf32>
    %mul_hs = stablehlo.multiply %sub, %relu6 : tensor<6x6x4x4xf32>
    %hardswish = stablehlo.divide %mul_hs, %cst_6_bcast : tensor<6x6x4x4xf32>

