      base_dilations = dense<[1, 1, 1, 1]> : tensor<4xi64>,
      window_dilations = dense<[1, 1, 1, 1]> : tensor<4xi64>,
      padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
      , reducer = @max_f32
      : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x2x2xf32>

    // ---- Mish: x * tanh(softplus(x)) ----
    // softplus(x) = log(1 + exp(x))
    %exp = stablehlo.exponential %maxpool : tensor<6x6x2x2xf32>
    %cst_1 = stablehlo.constant dense<1.0> : tensor<f32>
    %cst_1_bcast = stablehlo.broadcast_in_dim %cst_1, dims = [] : (tensor<f32>) -> tensor<6x6x2x2xf32>
    %exp_plus_1 = stablehlo.add %exp, %cst_1_bcast : tensor<6x6x2x2xf32>
    %softplus = stablehlo.log %exp_plus_1 : tensor<6x6x2x2xf32>
    %tanh_softplus = stablehlo.tanh %softplus : tensor<6x6x2x2xf32>
    %mish = stablehlo.multiply %maxpool, %tanh_softplus : tensor<6x6x2x2xf32>

    return %mish : tensor<6x6x2x2xf32>
