      // But in StableHLO, dimension_numbers = [batch, in_feature, spatial0, spatial1] x [out_feature, in_feature, spatial0, spatial1] -> [batch, out_feature, spatial0, spatial1]
      // So: [0,1,2,3] x [0,1,2,3] -> [0,1,2,3]
      // But for clarity, use the canonical form:
      dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
