  %sub = stablehlo.subtract %conv_bias, %cst_sub_broadcast : tensor<6x6x4x4xf32>

  // 4. HardSwish: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)
  %cst_3 = stablehlo.constant dense<3.0> : tensor<f32>
  %cst_6 = stablehlo.constant dense<6.0> : tensor<f32>
  %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_6_broadcast = "stablehlo.broadcast_in_dim"(%cst_6) {
    broadcast_dimensions = array<i64:>
  } : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %cst_0_broadcast = "stablehlo.broadcast_in_dim"(%cst_0) {
    broadcast_dimensions = array<i64:>
  } : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %cst_3_broadcast = "stablehlo.broadcast_in_dim"(%cst_3) {
    broadcast_dimensions = array<i64:>
  } : (tensor<f32>) -> tensor<6x6x4x4xf32>

  %add3 = stablehlo.add %sub, %cst_3_broadcast : tensor<6x6x4x4xf32>
  %relu6_0 = stablehlo.maximum %add3, %cst_0_broadcast : tensor<6x6x4x4xf32>
  %relu6 = stablehlo.minimum %relu6_0, %cst_6_broadcast : tensor<6x6x4x4xf32>
  %mul_hswish = stablehlo.multiply %sub, %relu6 : tensor<6x6x4x4xf32>
  %cst_6_broadcast2 = "stablehlo.broadcast_in_dim"(%cst_6) {
    broadcast_dimensions = array<i64:>
  } : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %hswish = stablehlo.divide %mul_hswish, %cst_6_broadcast2 : tensor<6x6x4x4xf32>

