    // a: [7,6] (k,i), b: [7,5] (k,j)
    // This is a contraction over k (dim 0 of both), producing [6,5] (i,j)
    // So: lhs_contracting_dimensions = [0], rhs_contracting_dimensions = [0]
    //     lhs: [7,6] (k,i), rhs: [7,5] (k,j)
    //     result: [6,5] (i,j)
    // Need to permute a to shape [6,7] (i,k) so that contraction is over k=1
    // Or, equivalently, use transpose on a and set contracting dims accordingly

    %a_t = stablehlo.transpose(%a, [1, 0]) : (tensor<7x6xf32>) -> tensor<6x7xf32>
    %b_t = stablehlo.transpose(%b, [1, 0]) : (tensor<7x5xf32>) -> tensor<5x7xf32>
    // Now a_t: [6,7] (i,k), b_t: [5,7] (j,k)
    // We want to contract over k (dim 1 of both), so:
    // lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]
    // Output: [6,5] (i,j)
    %out = "stablehlo.dot_general"(%a_t, %b_t) {
      dot_dimension_numbers = #stablehlo.dot<
        lhs_contracting_dimensions = [1],
        rhs_contracting_dimensions = [1]
      >
    } : (tensor<6x7xf32>, tensor<5x7xf32>) -> tensor<6x5xf32>
    // But this gives [6,5] (i,j) as desired, but axes are (i,j), not (i,j)
    // Actually, dot_general with these dims gives [6,5], but b_t's first dim is j, so output is (i,j)
    // So we need to transpose b to [7,5] -> [5,7], as above.

    return %out : tensor<6x5xf32>
  }
