module {
  func.func @main(
    %arg0: tensor<6x7x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
    %arg1: tensor<6xf32>,         // conv.bias [out_c]
    %arg2: tensor<6x7x6x6xf32>    // input [N, in_c, H, W]
  ) -> tensor<6x6x2x2xf32> {
    // Convolution
    // PyTorch: input[N, C_in, H, W], weight[C_out, C_in, kH, kW], bias[C_out]
    // StableHLO: lhs[N, C_in, H, W], rhs[C_out, C_in, kH, kW]
    // Output: [N, C_out, H_out, W_out]
    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

    // Add bias: bias shape [6] -> broadcast to [6,6,4,4]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x1x1x1xf32>
    %bias_bcast2 = "stablehlo.broadcast_in_dim"(%bias_bcast) {broadcast_dimensions = array<i64: 0,1,2,3>} : (tensor<6x1x1x1xf32>) -> tensor<6x6x4x4xf32>
    %conv_bias = stablehlo.add %conv, %bias_bcast2 : tensor<6x6x4x4xf32>

    // Subtract 0.5
    %cst_sub = stablehlo.constant dense<0.5> : tensor<f32>
    %cst_sub_bcast = "stablehlo.broadcast_in_dim"(%cst_sub) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %sub = stablehlo.subtract %conv_bias, %cst_sub_bcast : tensor<6x6x4x4xf32>

    // HardSwish: x * relu6(x+3) / 6
    // relu6(x) = min(max(x, 0), 6)
    %cst_3 = stablehlo.constant dense<3.0> : tensor<f32>
    %cst_6 = stablehlo.constant dense<6.0> : tensor<f32>
    %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>
    %cst_6_bcast = "stablehlo.broadcast_in_dim"(%cst_6) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %cst_0_bcast = "stablehlo.broadcast_in_dim"(%cst_0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %cst_3_bcast = "stablehlo.broadcast_in_dim"(%cst_3) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %add3 = stablehlo.add %sub, %cst_3_bcast : tensor<6x6x4x4xf32>
    %max0 = stablehlo.maximum %add3, %cst_0_bcast : tensor<6x6x4x4xf32>
    %relu6 = stablehlo.minimum %max0, %cst_6_bcast : tensor<6x6x4x4xf32>
    %hsw_mul = stablehlo.multiply %sub, %relu6 : tensor<6x6x4x4xf32>
    %cst_6_bcast2 = "stablehlo.broadcast_in_dim"(%cst_6) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
    %hswish = stablehlo.divide %hsw_mul, %cst_6_bcast2 : tensor<6x6x4x4xf32>

    // MaxPool2d(kernel_size=2, stride=2, padding=0)
    // Input: [6,6,4,4] -> Output: [6,6,2,2]
    // window_dimensions = [1,1,2,2], window_strides = [1,1,2,2], padding = 0
    %cst_neg_inf = stablehlo.constant dense<-3.4028235e+38> : tensor<f32>
    %maxpool = "stablehlo.reduce_window"(%hswish, %cst_neg_inf) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %m = stablehlo.maximum %a, %b : tensor<f32>
        stablehlo.return %m : tensor<f32>
    }) {
      window_dimensions = array<i64: 1, 1, 2, 2>,
      window_strides = array<i64: 1, 1, 2, 2>,
      padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
    } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

    // Mish: x * tanh(softplus(x)), softplus(x) = log(1 + exp(x))
    %exp = stablehlo.exponential %maxpool : tensor<6x6x2x2xf32>
    %cst_1 = stablehlo.constant dense<1.0> : tensor<f32>
    %cst_1_bcast = "stablehlo.broadcast_in_dim"(%cst_1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x2x2xf32>
    %exp_plus_1 = stablehlo.add %exp, %cst_1_bcast : tensor<6x6x2x2xf32>
    %softplus = stablehlo.log %exp_plus_1 : tensor<6x6x2x2xf32>
    %tanh = stablehlo.tanh %softplus : tensor<6x6x2x2xf32>
    %mish = stablehlo.multiply %maxpool, %tanh : tensor<6x6x2x2xf32>

    return %mish : tensor<6x6x2x2xf32>
  }
}
