module {
  // Entry function:
  // %arg0: tensor<7x7xf32>    -- gemm.weight (out_features x in_features)
  // %arg1: tensor<7xf32>      -- gemm.bias   (out_features)
  // %arg2: tensor<7xf32>      -- batch_norm.weight (gamma, out_features)
