    // %arg4: [6,7], %arg0: [7,7] (out_features x in_features)
    // Need to transpose weight to [in_features, out_features] for matmul
    %weight_t = "stablehlo.transpose"(%arg0) {permutation = dense<[1,0]> : tensor<2xi64>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // Dot: [6,7] x [7,7] -> [6,7]
    %gemm = "stablehlo.dot_general"(%arg4, %weight_t) {
      dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>,
      precision_config = []
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Broadcast bias [7] to [6,7]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %gemm_bias = "stablehlo.add"(%gemm, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // BatchNorm1d (training): y = gamma * (x - mean) / sqrt(var + eps) + beta
    // Compute mean over batch (dim 0): shape [7]
    %mean = "stablehlo.reduce"(%gemm_bias, %cst_zero) ({
      ^bb0(%x: tensor<f32>, %y: tensor<f32>):
        %sum = "stablehlo.add"(%x, %y) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%sum) : (tensor<f32>) -> ()
