    // mean: [7]
    // Broadcast mean to [6,7]
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = dense<[1]> : tensor<1xi64>} : (tensor<7xf32>) -> tensor<6x7xf32>
    // x - mean
    %centered = "stablehlo.subtract"(%gemm_bias, %mean_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // (x - mean)^2
    %centered_sq = "stablehlo.multiply"(%centered, %centered) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
