      // But stablehlo expects kernel [o, i, ...], so we need to keep kernel as [o, i, ...]
      // So, do NOT transpose, just reverse spatial dims
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, o, 0, 1, 2]>,
      feature_group_count = 1 : i64,
