      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      // [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]
      dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

    // 2. Add conv.bias (broadcast [7] to [6,7,4,4])
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x7x4x4xf32>

    // 3. BatchNorm (training mode): y = gamma * (x - mean) / sqrt(var + eps) + beta
    // Compute mean over [0,2,3] (N,H,W) for each channel
    // Reduce mean: dims [0,2,3] on [6,7,4,4] -> [7]
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %mean = "stablehlo.reduce"(%conv_bias, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>
    // Divide by N*H*W = 6*4*4 = 96
    %inv_n = stablehlo.constant dense<0.010416667> : tensor<f32> // 1/96
    %inv_n_bcast = "stablehlo.broadcast_in_dim"(%inv_n) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<7xf32>
    %mean = stablehlo.multiply %mean, %inv_n_bcast : tensor<7xf32>

    // Broadcast mean to [6,7,4,4]
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    // x - mean
    %centered = stablehlo.subtract %conv_bias, %mean_bcast : tensor<6x7x4x4xf32>

    // Variance: mean((x - mean)^2) over [0,2,3]
    %centered_sq = stablehlo.multiply %centered, %centered : tensor<6x7x4x4xf32>
    %var = "stablehlo.reduce"(%centered_sq, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>
    %var = stablehlo.multiply %var, %inv_n_bcast : tensor<7xf32>

    // Add epsilon for numerical stability
    %eps = stablehlo.constant dense<1.0000001E-5> : tensor<f32>
    %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<7xf32>
    %var_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>
    %std = stablehlo.sqrt %var_eps : tensor<7xf32>
    %std_bcast = "stablehlo.broadcast_in_dim"(%std) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

    // Normalize: (x - mean) / std
    %normed = stablehlo.divide %centered, %std_bcast : tensor<6x7x4x4xf32>

    // Apply gamma (bn.weight) and beta (bn.bias)
    %gamma_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %beta_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %scaled = stablehlo.multiply %normed, %gamma_bcast : tensor<6x7x4x4xf32>
    %shifted = stablehlo.add %scaled, %beta_bcast : tensor<6x7x4x4xf32>

    // 4. Multiply by scaling_factor=2.0
    %scale = stablehlo.constant dense<2.0> : tensor<f32>
    %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %out = stablehlo.multiply %shifted, %scale_bcast : tensor<6x7x4x4xf32>

    return %out : tensor<6x7x4x4xf32>
  }
}
