```mlir
module {
  // Entry function
  func.func @main(
    %arg0: tensor<7x8x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
    %arg1: tensor<7xf32>,         // conv.bias   [out_c]
    %arg2: tensor<7xf32>,         // bn.weight   [out_c]
    %arg3: tensor<7xf32>,         // bn.bias     [out_c]
    %arg4: tensor<6x8x6x6xf32>    // input       [N, in_c, H, W]
  ) -> tensor<6x7x4x4xf32> {
    // --- Convolution ---
    // PyTorch: input [N, C_in, H, W], weight [C_out, C_in, kH, kW], bias [C_out]
    // StableHLO: input [N, C_in, H, W], kernel [C_out, C_in, kH, kW]
    // Output: [N, C_out, H_out, W_out] = [6, 7, 4, 4]
    // Stride=1, Padding=0, Dilation=1

    %conv = "stablehlo.convolution"(%arg4, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[
        b, f, 0, 1
      ]x[
        o, i, 0, 1
      ]->[
        b, f, 0, 1
      ]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

    // --- Add conv.bias (broadcast over N, H, W) ---
    // conv.bias shape: [7] -> [1,7,1,1] -> broadcast to [6,7,4,4]
    %c1 = "stablehlo.constant"() {value = dense<1> : tensor<i64>} : () -> tensor<i64>
    %c4 = "stablehlo.constant"() {value = dense<4> : tensor<i64>} : () -> tensor<i64>
    %bias_reshape = "stablehlo.reshape"(%arg1) : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %bias_bcast = "stablehlo.broadcast_in_dim"(%bias_reshape) {broadcast_dimensions = array<i64: 1>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
    %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x7x4x4xf32>

    // --- BatchNorm: compute mean and variance over (N, H, W) for each channel ---
    // mean = sum(x, dims=[0,2,3]) / (N*H*W)
    // var = sum((x-mean)^2, dims=[0,2,3]) / (N*H*W)
    // Shapes: [6,7,4,4] -> mean/var: [7]

    // Reduce sum over dims 0,2,3
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %mean_sum = "stablehlo.reduce"(%conv_bias, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

    // Compute denominator (N*H*W = 6*4*4 = 96)
    %denom = "stablehlo.constant"() {value = dense<96.0> : tensor<f32>} : () -> tensor<f32>
    %mean = stablehlo.divide %mean_sum, %denom : tensor<7xf32>

    // Broadcast mean to [6,7,4,4] for (x - mean)
    %mean_reshape = "stablehlo.reshape"(%mean) : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_reshape) {broadcast_dimensions = array<i64: 1>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
    %centered = stablehlo.subtract %conv_bias, %mean_bcast : tensor<6x7x4x4xf32>

    // Square (x - mean)
    %centered_sq = stablehlo.multiply %centered, %centered : tensor<6x7x4x4xf32>

    // Reduce sum for variance
    %var_sum = "stablehlo.reduce"(%centered_sq, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>
    %var = stablehlo.divide %var_sum, %denom : tensor<7xf32>

    // --- BatchNorm: normalize ---
    // y = (x - mean) / sqrt(var + eps) * weight + bias
    // eps = 1e-5
    %eps = "stablehlo.constant"() {value = dense<1.0000000116860974E-5> : tensor<f32>} : () -> tensor<f32>
    %var_eps = stablehlo.add %var, %eps : tensor<7xf32>
    %invstd = stablehlo.rsqrt %var_eps : tensor<7xf32>

    // Broadcast invstd to [6,7,4,4]
    %invstd_reshape = "stablehlo.reshape"(%invstd) : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %invstd_bcast = "stablehlo.broadcast_in_dim"(%invstd_reshape) {broadcast_dimensions = array<i64: 1>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
    %normed = stablehlo.multiply %centered, %invstd_bcast : tensor<6x7x4x4xf32>

    // Broadcast bn.weight and bn.bias to [6,7,4,4]
    %bnw_reshape = "stablehlo.reshape"(%arg2) : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %bnw_bcast = "stablehlo.broadcast_in_dim"(%bnw_reshape) {broadcast_dimensions = array<i64: 1>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
    %bnb_reshape = "stablehlo.reshape"(%arg3) : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %bnb_bcast = "stablehlo.broadcast_in_dim"(%bnb_reshape) {broadcast_dimensions = array<i64: 1>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>

    %normed_scaled = stablehlo.multiply %normed, %bnw_bcast : tensor<6x7x4x4xf32>
