    %var_eps = "stablehlo.add"(%var_bn, %c_epsilon) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>

    // sqrt(var + eps)
    %var_sqrt = "stablehlo.sqrt"(%var_eps) : tensor<7xf32> -> tensor<7xf32>

    // Broadcast sqrt(var+eps) to [6,7,4,4]
    %var_sqrt_bcast = "stablehlo.broadcast_in_dim"(%var_sqrt) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

    // Normalize: (x - mean) / sqrt(var + eps)
    %normed = "stablehlo.divide"(%centered, %var_sqrt_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    // Apply scale (bn.weight) and shift (bn.bias)
    // Broadcast bn.weight and bn.bias to [6,7,4,4]
    %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %normed_scaled = "stablehlo.multiply"(%normed, %bn_weight_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    %normed_shifted = "stablehlo.add"(%normed_scaled, %bn_bias_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    // Add conv.bias (broadcast to [6,7,4,4])
    %conv_bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %with_bias = "stablehlo.add"(%normed_shifted, %conv_bias_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    // Final scaling: x * 2.0
    %scaled = "stablehlo.multiply"(%with_bias, %c2_f32) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

    return %scaled : tensor<6x7x4x4xf32>
  }
}
