module {
  // Entry function
  func.func @main(
      %conv_weight: tensor<7x8x3x3xf32>,   // conv.weight
      %conv_bias: tensor<7xf32>,           // conv.bias
      %bn_weight: tensor<7xf32>,           // bn.weight (gamma)
      %bn_bias: tensor<7xf32>,             // bn.bias (beta)
      %input: tensor<6x8x6x6xf32>          // input
    ) -> tensor<6x7x4x4xf32> {
    // Constants
    %cst_eps = stablehlo.constant dense<0.00001> : tensor<f32>
    %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
    %cst_one = stablehlo.constant dense<1.0> : tensor<f32>
    %cst_scaling = stablehlo.constant dense<2.0> : tensor<f32>

    // 1. Convolution
    // PyTorch: NCHW, StableHLO: NCHW
    // conv.weight: [out_c, in_c, kh, kw] = [7,8,3,3]
    // input: [N, C, H, W] = [6,8,6,6]
    // bias: [7]
    // Stride=1, Padding=0, Dilation=1, Groups=1
    %conv = stablehlo.convolution(
      %input, %conv_weight,
      window_strides = [1, 1],
      padding = [0, 0, 0, 0],
      lhs_dilation = [1, 1],
      rhs_dilation = [1, 1],
      dimension_numbers = [
        // input: NCHW, kernel: OIHW, output: NCHW
        [0, 1, 2, 3], // input: N, C, H, W
        [0, 1, 2, 3], // kernel: O, I, H, W
        [0, 1, 2, 3]  // output: N, C, H, W
      ],
      feature_group_count = 1,
      batch_group_count = 1,
      precision_config = []
    ) : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

    // 2. Add bias (broadcast over N,H,W)
    // conv_bias: [7] -> [1,7,1,1]
    %conv_bias_bcast = stablehlo.broadcast_in_dim %conv_bias, dims = [1] : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %conv_bias_bcast_full = stablehlo.broadcast_in_dim %conv_bias_bcast, dims = [0,1,2,3] : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
    %conv_plus_bias = stablehlo.add %conv, %conv_bias_bcast_full : tensor<6x7x4x4xf32>

    // 3. BatchNorm (training mode, use batch statistics)
    // Compute mean and variance over (N,H,W) for each channel
    // Reduce dimensions: [0,2,3]
    %mean = stablehlo.reduce
      %conv_plus_bias, %cst_zero
      dimensions = [0,2,3]
      {
        ^bb0(%a: f32, %b: f32):
          %add = stablehlo.add %a, %b : f32
          stablehlo.return %add : f32
      }
      : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>
    // Count of elements per channel: 6*4*4 = 96
    %count = stablehlo.constant dense<96.0> : tensor<f32>
    %mean = stablehlo.divide %mean, %count : tensor<7xf32>

    // Broadcast mean to [6,7,4,4]
    %mean_bcast = stablehlo.broadcast_in_dim %mean, dims = [1] : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %mean_bcast_full = stablehlo.broadcast_in_dim %mean_bcast, dims = [0,1,2,3] : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>

    // x - mean
    %centered = stablehlo.subtract %conv_plus_bias, %mean_bcast_full : tensor<6x7x4x4xf32>

    // Variance: mean((x - mean)^2) over [0,2,3]
    %centered_sq = stablehlo.multiply %centered, %centered : tensor<6x7x4x4xf32>
    %var = stablehlo.reduce
      %centered_sq, %cst_zero
      dimensions = [0,2,3]
      {
        ^bb0(%a: f32, %b: f32):
          %add = stablehlo.add %a, %b : f32
          stablehlo.return %add : f32
      }
      : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>
    %var = stablehlo.divide %var, %count : tensor<7xf32>

    // variance + eps
    %var_eps = stablehlo.add %var, %cst_eps : tensor<7xf32>
    // sqrt(variance + eps)
    %std = stablehlo.sqrt %var_eps : tensor<7xf32>
    // Broadcast std to [6,7,4,4]
    %std_bcast = stablehlo.broadcast_in_dim %std, dims = [1] : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %std_bcast_full = stablehlo.broadcast_in_dim %std_bcast, dims = [0,1,2,3] : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>

    // Normalize: (x - mean) / sqrt(var + eps)
    %normed = stablehlo.divide %centered, %std_bcast_full : tensor<6x7x4x4xf32>

    // Apply gamma (bn.weight) and beta (bn.bias)
    // bn.weight: [7] -> [1,7,1,1] -> [6,7,4,4]
    %gamma_bcast = stablehlo.broadcast_in_dim %bn_weight, dims = [1] : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %gamma_bcast_full = stablehlo.broadcast_in_dim %gamma_bcast, dims = [0,1,2,3] : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
    %normed_scaled = stablehlo.multiply %normed, %gamma_bcast_full : tensor<6x7x4x4xf32>

    %beta_bcast = stablehlo.broadcast_in_dim %bn_bias, dims = [1] : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %beta_bcast_full = stablehlo.broadcast_in_dim %beta_bcast, dims = [0,1,2,3] : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
    %bn_out = stablehlo.add %normed_scaled, %beta_bcast_full : tensor<6x7x4x4xf32>

    // 4. Multiply by scaling factor (2.0)
    %scaling_bcast = stablehlo.broadcast_in_dim %cst_scaling, dims = [] : (tensor<f32>) -> tensor<1x1x1x1xf32>
    %scaling_bcast_full = stablehlo.broadcast_in_dim %scaling_bcast, dims = [0,1,2,3] : (tensor<1x1x1x1xf32>) -> tensor<6x7x4x4xf32>
    %out = stablehlo.multiply %bn_out, %scaling_bcast_full : tensor<6x7x4x4xf32>

    return %out : tensor<6x7x4x4xf32>
  }
}
