module {
  func.func @main(
    %arg0: tensor<7x8x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
    %arg1: tensor<7xf32>,         // conv.bias [out_c]
    %arg2: tensor<6x8x8x8xf32>    // input [N, in_c, H, W]
  ) -> tensor<6xf32> {
    // 1. Convolution: input [N, in_c, H, W], weight [out_c, in_c, kH, kW]
    // PyTorch: out = conv2d(input, weight, bias, stride=1, padding=0)
    // StableHLO expects input [N, in_c, H, W], filter [out_c, in_c, kH, kW]
    // Output shape: [N, out_c, H_out, W_out] where H_out = W_out = 8-3+1 = 6

    %conv = "stablehlo.convolution"(
      %arg2, %arg0
    ) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64,
      dimension_numbers = #stablehlo.conv<lhs_spec = [0, 1, 2, 3], rhs_spec = [0, 1, 2, 3], out_spec = [0, 1, 2, 3]>
    } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

    // 2. Add bias: bias shape [7], need to broadcast to [6,7,6,6]
    // Broadcast bias [7] to [6,7,6,6] along dim 1
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = dense<[1]> : tensor<1xi64>
    } : (tensor<7xf32>) -> tensor<6x7x6x6xf32>

    %biased = "stablehlo.add"(%conv, %bias_bcast)
      : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

    // 3. AvgPool2d with kernel_size=4, stride=4, no padding
    // ReduceWindow with window_dimensions=[1,1,4,4], window_strides=[1,1,4,4]
    // Pool over spatial dims (2,3)
    // For each window, sum and divide by 16 (4x4)
    %pool = "stablehlo.reduce_window"(%biased, %cst_zero) {
      window_dimensions = dense<[1, 1, 4, 4]> : tensor<4xi64>,
      window_strides = dense<[1, 1, 4, 4]> : tensor<4xi64>,
      base_dilations = dense<[1, 1, 1, 1]> : tensor<4xi64>,
      window_dilations = dense<[1, 1, 1, 1]> : tensor<4xi64>,
      padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
    } ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }) : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x7x2x2xf32>

    // Divide by 16.0 to get average
    %cst_16 = "stablehlo.constant"() { value = dense<16.0> : tensor<f32> } : () -> tensor<f32>
    // Broadcast 16.0 to [6,7,2,2]
    %cst_16_bcast = "stablehlo.broadcast_in_dim"(%cst_16) {
      broadcast_dimensions = dense<[]> : tensor<0xi64>
    } : (tensor<f32>) -> tensor<6x7x2x2xf32>
    %avgpooled = "stablehlo.divide"(%pool, %cst_16_bcast)
      : (tensor<6x7x2x2xf32>, tensor<6x7x2x2xf32>) -> tensor<6x7x2x2xf32>

