    %biased = stablehlo.add %conv, %bias_bcast : tensor<6x7x6x6xf32>

    // 3. AvgPool2d(kernel_size=4): window 4x4, stride 4, no padding
    // Reduce_window with add, then divide by 16.0
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %pooled = "stablehlo.reduce_window"(%biased, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %s : tensor<f32>
