    %exp = stablehlo.exponential %neg : tensor<6x7x2x2xf32>
    %denom = stablehlo.add %c1_bcast, %exp : tensor<6x7x2x2xf32>
    %sigmoid = stablehlo.divide %c1_bcast, %denom : tensor<6x7x2x2xf32>

    // 5. Sum over dims [1,2,3] (out_channels, pooled_H, pooled_W) -> [6]
    %sum_init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %sum = "stablehlo.reduce"(%sigmoid, %sum_init) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %s : tensor<f32>
    }) {dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x2x2xf32>, tensor<f32>) -> tensor<6xf32>

    return %sum : tensor<6xf32>
  }
