module {
  func.func @main(
    %arg0: tensor<7x8x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
    %arg1: tensor<7xf32>,         // conv.bias [out_c]
    %arg2: tensor<6x8x8x8xf32>    // input [N, in_c, H, W]
  ) -> tensor<6xf32> {
    // 1. Convolution: input [N, in_c, H, W], weight [out_c, in_c, kH, kW]
    // PyTorch: input [N, C_in, H, W], weight [C_out, C_in, kH, kW]
    // StableHLO: input [N, C_in, H, W], kernel [C_out, C_in, kH, kW]
    // Output: [N, C_out, H_out, W_out]
    // Stride=1, Padding=0, Dilation=1

    // Convolution parameters
    // input: [6,8,8,8], weight: [7,8,3,3]
    // Output: [6,7,6,6]
    // H_out = floor((0 + (8-1)*1 + 1 + 0 - ((3-1)*1 + 1))/1) + 1 = floor((0+7+1+0-2)/1)+1 = floor(6)+1 = 7
    // Correction: ((0 + (8-1)*1 + 1 + 0 - ((3-1)*1 + 1))/1) + 1 = ((0+7+1+0-2)/1)+1 = (6/1)+1 = 6+1=7
    // But PyTorch Conv2d with no padding, stride=1, kernel=3: output = (8-3)//1+1 = 6
    // So output shape: [6,7,6,6]

    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

    // 2. Add bias: bias shape [7] -> broadcast to [6,7,6,6]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<7xf32>) -> tensor<6x7x6x6xf32>
    %biased = stablehlo.add %conv, %bias_bcast : tensor<6x7x6x6xf32>

    // 3. AvgPool2d with kernel_size=4, stride=4, no padding
    // PyTorch default: stride=kernel_size, padding=0
    // Window dims: [1,1,4,4] (don't pool over batch or channel)
    // Strides: [1,1,4,4]
    // Padding: [[0,0],[0,0],[0,0],[0,0]]
    // Reduce function: add, then divide by 16 (4x4)

    // Initial value for reduce_window: 0.0
    %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
    %pooled = "stablehlo.reduce_window"(%biased, %cst_zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {
      window_dimensions = array<i64: 1, 1, 4, 4>,
      window_strides = array<i64: 1, 1, 4, 4>,
      base_dilations = array<i64: 1, 1, 1, 1>,
      window_dilations = array<i64: 1, 1, 1, 1>,
      padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
    } : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x7x2x2xf32>

    // Divide by 16.0 to get average
    %cst_16 = stablehlo.constant dense<16.0> : tensor<f32>
    %pooled_avg = stablehlo.divide %pooled, %cst_16 : tensor<6x7x2x2xf32>

