    %2 = stablehlo.add %0, %1 : tensor<6x7xf32>
    // torch.max(x, dim=1, keepdim=True).values
    // Reduce along axis 1, keepdim
    %3 = stablehlo.constant dense<-3.40282347E+38> : tensor<f32>
    %4 = stablehlo.broadcast_in_dim %3, dims = [] : (tensor<f32>) -> tensor<6x1xf32>
    %5 = stablehlo.reduce %2, %4
      reducer = @max_f32
      dimensions = [1] : (tensor<6x7xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
