module {
  func.func @main(
    %weight: tensor<7x6x3x3xf32>, 
    %bias: tensor<7xf32>, 
    %input: tensor<6x6x8x8xf32>
  ) -> tensor<6x7x6x6xf32> {
    // Convolution: input [N=6, Cin=6, H=8, W=8], weight [Cout=7, Cin=6, KH=3, KW=3]
    // PyTorch: out = conv2d(input, weight, bias, stride=1, padding=0)
    // StableHLO expects input [N, Cin, H, W], weight [Cout, Cin, KH, KW]
    // Output shape: [N=6, Cout=7, H_out=6, W_out=6]
    %conv = stablehlo.convolution(
      %input, %weight
    ) {
      window_strides = dense<[1, 1]> : tensor<2xi64>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64,
      dimension_numbers = #stablehlo.convolution<
        input_batch_dimension = 0,
        input_feature_dimension = 1,
        input_spatial_dimensions = [2, 3],
        kernel_output_feature_dimension = 0,
        kernel_input_feature_dimension = 1,
        kernel_spatial_dimensions = [2, 3],
        output_batch_dimension = 0,
        output_feature_dimension = 1,
        output_spatial_dimensions = [2, 3]
      >
    } : (tensor<6x6x8x8xf32>, tensor<7x6x3x3xf32>) -> tensor<6x7x6x6xf32>

    // Bias add: bias [7] -> [1,7,1,1], broadcast to [6,7,6,6]
    %bias_bcast = stablehlo.broadcast_in_dim %bias, dims = [1] 
      : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %bias_bcast_full = stablehlo.broadcast_in_dim %bias_bcast, dims = [0,1,2,3]
      : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>
    %biased = stablehlo.add %conv, %bias_bcast_full
      : tensor<6x7x6x6xf32>

    // Mish(x) = x * tanh(softplus(x)), softplus(x) = log(1 + exp(x))
    // We'll implement Mish twice in sequence.

    // First Mish
    // softplus(x)
    %exp1 = stablehlo.exponential %biased : tensor<6x7x6x6xf32>
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %one_bcast = stablehlo.broadcast_in_dim %one, dims = [] : (tensor<f32>) -> tensor<6x7x6x6xf32>
    %exp1_plus_one = stablehlo.add %exp1, %one_bcast : tensor<6x7x6x6xf32>
    %softplus1 = stablehlo.log %exp1_plus_one : tensor<6x7x6x6xf32>
    %tanh1 = stablehlo.tanh %softplus1 : tensor<6x7x6x6xf32>
    %mish1 = stablehlo.multiply %biased, %tanh1 : tensor<6x7x6x6xf32>

    // Second Mish
    // softplus(x)
    %exp2 = stablehlo.exponential %mish1 : tensor<6x7x6x6xf32>
    %exp2_plus_one = stablehlo.add %exp2, %one_bcast : tensor<6x7x6x6xf32>
    %softplus2 = stablehlo.log %exp2_plus_one : tensor<6x7x6x6xf32>
    %tanh2 = stablehlo.tanh %softplus2 : tensor<6x7x6x6xf32>
    %mish2 = stablehlo.multiply %mish1, %tanh2 : tensor<6x7x6x6xf32>

    return %mish2 : tensor<6x7x6x6xf32>
  }
}
