func.func @main(
  %arg0: tensor<7x6x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
  %arg1: tensor<7xf32>,         // conv.bias   [out_c]
  %arg2: tensor<6x6x8x8xf32>    // input       [N, in_c, H, W]
) -> tensor<6x7x6x6xf32> {
  // Convolution: input [6,6,8,8], weight [7,6,3,3], output [6,7,6,6]
  // PyTorch: NCHW, weight [out_c, in_c, kH, kW]
  // StableHLO: [N, C, H, W], weight [O, I, kH, kW]
  // dimension_numbers: [N, C, H, W] x [O, I, kH, kW] -> [N, O, H, W]
  // kernel spatial: 2D, stride=1, padding=1 (to preserve 8->6 with 3x3 kernel)
  // Output shape: [6,7,6,6]

  // Padding: (8 + 2*1 - 3) / 1 + 1 = 8
  // But PyTorch default is padding=0, so for 8x8 input, 3x3 kernel, stride=1:
  // output = floor((8 - 3)/1 + 1) = 6
  // So, padding=0.

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[
      n, c, 0, 1
    ]x[
      o, i, 0, 1
    ]->[
      n, o, 0, 1
    ]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x6x8x8xf32>, tensor<7x6x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: bias shape [7] -> broadcast to [6,7,6,6]
  // Broadcast bias: [7] -> [6,7,6,6], dims=[1]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x6x6xf32>

  %biased = stablehlo.add %conv, %bias_broadcast : tensor<6x7x6x6xf32>

  // Mish(x) = x * tanh(softplus(x)), softplus(x) = log(1 + exp(x))
  // First Mish
  %exp1 = stablehlo.exponential %biased : tensor<6x7x6x6xf32>
  %one_c = stablehlo.constant dense<1.0> : tensor<f32>
  %one = "stablehlo.broadcast_in_dim"(%one_c) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x6x6xf32>
  %exp1_plus_one = stablehlo.add %exp1, %one : tensor<6x7x6x6xf32>
  %softplus1 = stablehlo.log %exp1_plus_one : tensor<6x7x6x6xf32>
  %tanh1 = stablehlo.tanh %softplus1 : tensor<6x7x6x6xf32>
  %mish1 = stablehlo.multiply %biased, %tanh1 : tensor<6x7x6x6xf32>

  // Second Mish
  %exp2 = stablehlo.exponential %mish1 : tensor<6x7x6x6xf32>
  %exp2_plus_one = stablehlo.add %exp2, %one : tensor<6x7x6x6xf32>
  %softplus2 = stablehlo.log %exp2_plus_one : tensor<6x7x6x6xf32>
  %tanh2 = stablehlo.tanh %softplus2 : tensor<6x7x6x6xf32>
  %mish2 = stablehlo.multiply %mish1, %tanh2 : tensor<6x7x6x6xf32>

  return %mish2 : tensor<6x7x6x6xf32>
}
